INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6bd6de22-634c-4320-9879-8f6429b64229', 'fa2f0e03-c60c-56b5-b9c1-2a2ec66710d8', '$2.0 \times 10^{-4}$ හා $7.8$', '$2.0 \times 10^{-4}$ හා $7.8$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d5f795c6-4392-5d9c-b3bf-7034bf5057d0', '3606931e-d7be-5c30-a36e-e29533680455', 19, '<p>සෝඩියම් අයනයෙහි සම්මත සජලන එන්තැල්පියට අදාළ නිවැරදි ප්‍රතික්‍රියාව වනුයේ,</p>', '<p>සෝඩියම් අයනයෙහි සම්මත සජලන එන්තැල්පියට අදාළ නිවැරදි ප්‍රතික්‍රියාව වනුයේ,</p>', NULL, 'සම්මත සජලන එන්තැල්පිය යනු, වායුමය අවස්ථාවේ පවතින අයන මවුලයක් ජල අතිරික්තයක දියකර අනන්ත තනුක ජලීය ද්‍රාවණයක් සෑදීමේදී සිදුවන එන්තැල්පි වෙනසයි. එය $Na^+(g) + \text{aq (අතිරික්ත ජලය)} \rightarrow Na^+(aq)$ ලෙස නිරූපණය කෙරේ.', 'සම්මත සජලන එන්තැල්පිය යනු, වායුමය අවස්ථාවේ පවතින අයන මවුලයක් ජල අතිරික්තයක දියකර අනන්ත තනුක ජලීය ද්‍රාවණයක් සෑදීමේදී සිදුවන එන්තැල්පි වෙනසයි. එය $Na^+(g) + \text{aq (අතිරික්ත ජලය)} \rightarrow Na^+(aq)$ ලෙස නිරූපණය කෙරේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('49857171-2491-4dcd-bd3b-f8ae198460da', 'd5f795c6-4392-5d9c-b3bf-7034bf5057d0', '$Na^+(g) + OH^-(aq) \rightarrow NaOH(s)$', '$Na^+(g) + OH^-(aq) \rightarrow NaOH(s)$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c8892a2f-243a-45ad-b32e-ceb77ee85520', 'd5f795c6-4392-5d9c-b3bf-7034bf5057d0', '$NaCl(g) + H_2O(l) \rightarrow Na^+(aq) + OH^-(aq) + HCl(aq)$', '$NaCl(g) + H_2O(l) \rightarrow Na^+(aq) + OH^-(aq) + HCl(aq)$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('27d3671a-26ec-4e28-812a-1128837e67a8', 'd5f795c6-4392-5d9c-b3bf-7034bf5057d0', '$Na^+(g) + H_2O(l) \rightarrow Na^+(aq)$', '$Na^+(g) + H_2O(l) \rightarrow Na^+(aq)$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aaccb435-b405-4adc-bd8f-e016c579ecd9', 'd5f795c6-4392-5d9c-b3bf-7034bf5057d0', '$Na^+(g) + H_2O(l) \rightarrow Na^+(aq) + OH^-(aq) + H^+(aq)$', '$Na^+(g) + H_2O(l) \rightarrow Na^+(aq) + OH^-(aq) + H^+(aq)$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2a819273-7e1b-4a21-b081-5e1bb675b51c', 'd5f795c6-4392-5d9c-b3bf-7034bf5057d0', '$Na^+(g) + Cl^-(g) + H_2O(l) \rightarrow Na^+(aq) + Cl^-(aq)$', '$Na^+(g) + Cl^-(g) + H_2O(l) \rightarrow Na^+(aq) + Cl^-(aq)$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7824ed10-0796-5238-b5bd-e4e613bbd2f7', '3606931e-d7be-5c30-a36e-e29533680455', 20, '<p>මීතේන් ක්ලෝරිනීකරණයේ පියවරක් නොවන්නේ පහත දැක්වෙන ඒවායින් කුමක්ද?</p>', '<p>මීතේන් ක්ලෝරිනීකරණයේ පියවරක් නොවන්නේ පහත දැක්වෙන ඒවායින් කුමක්ද?</p>', NULL, 'මීතේන් වල මුක්ත ඛණ්ඩක ආදේශ ප්‍රතික්‍රියාවේ (හරිතකරණයේ) ව්‍යාප්ති පියවරවලදී හයිඩ්‍රජන් මුක්ත ඛණ්ඩක ($H^\bullet$) කිසිවිටෙකත් නිපදවෙන්නේ නැත. 5 වන පියවර සම්පූර්ණයෙන්ම වැරදි ප්‍රතික්‍රියාවකි. (නිවැරදි ව්‍යාප්ති ප්‍රතික්‍රියාව විය යුත්තේ $^\bullet CH_2Cl + Cl_2 \rightarrow CH_2Cl_2 + Cl^\bullet$ ය).', 'මීතේන් වල මුක්ත ඛණ්ඩක ආදේශ ප්‍රතික්‍රියාවේ (හරිතකරණයේ) ව්‍යාප්ති පියවරවලදී හයිඩ්‍රජන් මුක්ත ඛණ්ඩක ($H^\bullet$) කිසිවිටෙකත් නිපදවෙන්නේ නැත. 5 වන පියවර සම්පූර්ණයෙන්ම වැරදි ප්‍රතික්‍රියාවකි. (නිවැරදි ව්‍යාප්ති ප්‍රතික්‍රියාව විය යුත්තේ $^\bullet CH_2Cl + Cl_2 \rightarrow CH_2Cl_2 + Cl^\bullet$ ය).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cc31b207-6372-49c9-aad1-6419c9df7810', '7824ed10-0796-5238-b5bd-e4e613bbd2f7', '$Cl_2 \rightarrow 2Cl^\bullet$', '$Cl_2 \rightarrow 2Cl^\bullet$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d91c59b5-8456-4088-90b7-6d2515211b32', '7824ed10-0796-5238-b5bd-e4e613bbd2f7', '$CH_4 + Cl^\bullet \rightarrow ^\bullet CH_3 + HCl$', '$CH_4 + Cl^\bullet \rightarrow ^\bullet CH_3 + HCl$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('78540188-90c3-46db-b112-c372593f6a76', '7824ed10-0796-5238-b5bd-e4e613bbd2f7', '$^\bullet CH_3 + Cl_2 \rightarrow CH_3Cl + Cl^\bullet$', '$^\bullet CH_3 + Cl_2 \rightarrow CH_3Cl + Cl^\bullet$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('95cb76bc-5448-4a65-a6b8-e0324b57c044', '7824ed10-0796-5238-b5bd-e4e613bbd2f7', '$CH_3Cl + Cl^\bullet \rightarrow ^\bullet CH_2Cl + HCl$', '$CH_3Cl + Cl^\bullet \rightarrow ^\bullet CH_2Cl + HCl$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c5f37222-da2d-4e8a-b517-af212b2e9d0e', '7824ed10-0796-5238-b5bd-e4e613bbd2f7', '$^\bullet CH_2Cl + HCl \rightarrow CH_2Cl_2 + H^\bullet$', '$^\bullet CH_2Cl + HCl \rightarrow CH_2Cl_2 + H^\bullet$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7083d678-858f-5097-bff8-4f30e4a076e2', '3606931e-d7be-5c30-a36e-e29533680455', 21, '<p>තාත්වික වායුවක අවධි උෂ්ණත්වය සම්බන්ධයෙන් පහත සඳහන් කුමන වගන්තිය නිවැරදි වේද?</p>', '<p>තාත්වික වායුවක අවධි උෂ්ණත්වය සම්බන්ධයෙන් පහත සඳහන් කුමන වගන්තිය නිවැරදි වේද?</p>', NULL, 'අවධි උෂ්ණත්වය (Critical Temperature) යනු යම් වායුවක් ද්‍රවයක් ලෙස පැවතිය හැකි ඉහළම උෂ්ණත්වයයි. එම උෂ්ණත්වයේදී වායු හා ද්‍රව කලාප අතර වෙනසක් නොපෙනෙන අතර, ඊට ඉහළ උෂ්ණත්වවලදී වායුවක් කොතරම් පීඩනයකට ලක් කළද ද්‍රවීකරණය කළ නොහැක.', 'අවධි උෂ්ණත්වය (Critical Temperature) යනු යම් වායුවක් ද්‍රවයක් ලෙස පැවතිය හැකි ඉහළම උෂ්ණත්වයයි. එම උෂ්ණත්වයේදී වායු හා ද්‍රව කලාප අතර වෙනසක් නොපෙනෙන අතර, ඊට ඉහළ උෂ්ණත්වවලදී වායුවක් කොතරම් පීඩනයකට ලක් කළද ද්‍රවීකරණය කළ නොහැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9cd5a83e-9f0d-4b8f-9097-8bd5a313281e', '7083d678-858f-5097-bff8-4f30e4a076e2', 'එය අන්තර්අණුක බල නොසලකා හැරිය හැකි වන උෂ්ණත්වයයි.', 'එය අන්තර්අණුක බල නොසලකා හැරිය හැකි වන උෂ්ණත්වයයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0f43bf9d-1d72-4a5a-ae5e-6d8e125572e3', '7083d678-858f-5097-bff8-4f30e4a076e2', 'එය වායුව ද්‍රවීකරණය කළ හැකි අඩුම පීඩනයට අදාළ උෂ්ණත්වයයි.', 'එය වායුව ද්‍රවීකරණය කළ හැකි අඩුම පීඩනයට අදාළ උෂ්ණත්වයයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('710371c7-910d-4cb1-8eaf-32d6567c38ac', '7083d678-858f-5097-bff8-4f30e4a076e2', 'එය වායුව එහි ඝනය සමග සමතුලිතව ඇති උෂ්ණත්වයයි.', 'එය වායුව එහි ඝනය සමග සමතුලිතව ඇති උෂ්ණත්වයයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('34e9942e-206b-4bcc-ae05-2c37a9744e3f', '7083d678-858f-5097-bff8-4f30e4a076e2', 'එය වායු කලාපය හා ද්‍රව කලාපය සමතුලිතව පවතින වැඩිම උෂ්ණත්වයයි.', 'එය වායු කලාපය හා ද්‍රව කලාපය සමතුලිතව පවතින වැඩිම උෂ්ණත්වයයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('681ca77e-44cd-42b4-9d09-76c966c7a76a', '7083d678-858f-5097-bff8-4f30e4a076e2', 'එය ඕනෑම පීඩනයකදී වැන්ඩ''වාල්ස් සමීකරණය මගින් ලබාදෙන උෂ්ණත්වයයි.', 'එය ඕනෑම පීඩනයකදී වැන්ඩ''වාල්ස් සමීකරණය මගින් ලබාදෙන උෂ්ණත්වයයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('40ab7368-d247-5b7c-911a-2b01489f9635', '3606931e-d7be-5c30-a36e-e29533680455', 22, '<p>පරීක්ෂණයකදී, වැඩිපුර $N_2$ වායුව සමග $Mg$ ලෝහය ප්‍රතික්‍රියා කිරීමට සලස්වා, ලැබෙන ඵලය $H_2O$ සමග ප්‍රතික්‍රියා කරවන ලදී. සම්මත උෂ්ණත්වයේදී ($273 \text{ K}$) සහ පීඩනයේදී ($1.0 \text{ atm}$) පිට වූ වායුවේ පරිමාව $672 \text{ cm}^3$ විය. පරීක්ෂණයේදී භාවිත කළ $Mg$ හි ස්කන්ධය වනුයේ,<br><br>($273 \text{ K}$ හා $1.0 \text{ atm}$ හිදී වායුවේ $1.0 \text{ mol}$, $22.4 \text{ dm}^3$ පරිමාවක් අත් කරගන්නා බව උපකල්පනය කරන්න. සාපේක්ෂ පරමාණුක ස්කන්ධය: $Mg=24$)</p>', '<p>පරීක්ෂණයකදී, වැඩිපුර $N_2$ වායුව සමග $Mg$ ලෝහය ප්‍රතික්‍රියා කිරීමට සලස්වා, ලැබෙන ඵලය $H_2O$ සමග ප්‍රතික්‍රියා කරවන ලදී. සම්මත උෂ්ණත්වයේදී ($273 \text{ K}$) සහ පීඩනයේදී ($1.0 \text{ atm}$) පිට වූ වායුවේ පරිමාව $672 \text{ cm}^3$ විය. පරීක්ෂණයේදී භාවිත කළ $Mg$ හි ස්කන්ධය වනුයේ,<br><br>($273 \text{ K}$ හා $1.0 \text{ atm}$ හිදී වායුවේ $1.0 \text{ mol}$, $22.4 \text{ dm}^3$ පරිමාවක් අත් කරගන්නා බව උපකල්පනය කරන්න. සාපේක්ෂ පරමාණුක ස්කන්ධය: $Mg=24$)</p>', NULL, 'සිදුවන ප්‍රතික්‍රියා:<br>$3Mg + N_2 \rightarrow Mg_3N_2$<br>$Mg_3N_2 + 6H_2O \rightarrow 3Mg(OH)_2 + 2NH_3$<br>පිටවන වායුව $NH_3$ වේ. එහි මවුල ගණන $= \frac{672 \times 10^{-3} \text{ dm}^3}{22.4 \text{ dm}^3 \text{ mol}^{-1}} = 0.03 \text{ mol}$.<br>මවුල අනුපාතය අනුව $Mg$ මවුල ගණන $= 0.03 \times \frac{3}{2} = 0.045 \text{ mol}$.<br>$Mg$ ස්කන්ධය $= 0.045 \text{ mol} \times 24 \text{ g mol}^{-1} = 1.08 \text{ g}$.', 'සිදුවන ප්‍රතික්‍රියා:<br>$3Mg + N_2 \rightarrow Mg_3N_2$<br>$Mg_3N_2 + 6H_2O \rightarrow 3Mg(OH)_2 + 2NH_3$<br>පිටවන වායුව $NH_3$ වේ. එහි මවුල ගණන $= \frac{672 \times 10^{-3} \text{ dm}^3}{22.4 \text{ dm}^3 \text{ mol}^{-1}} = 0.03 \text{ mol}$.<br>මවුල අනුපාතය අනුව $Mg$ මවුල ගණන $= 0.03 \times \frac{3}{2} = 0.045 \text{ mol}$.<br>$Mg$ ස්කන්ධය $= 0.045 \text{ mol} \times 24 \text{ g mol}^{-1} = 1.08 \text{ g}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
