INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('198886af-0d19-4506-adb2-984b0905c8c3', '7573f0f3-b796-540f-878b-912ca5fd1b1c', 'වායුසමීකරණ හා ශීතකරණ අළුත්වැඩියාවේදී පිටවන වායුන් ය.', 'වායුසමීකරණ හා ශීතකරණ අළුත්වැඩියාවේදී පිටවන වායුන් ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c508689d-c130-46b5-b670-8e6553d9de0d', '7573f0f3-b796-540f-878b-912ca5fd1b1c', 'නාගරික ඝන අපද්‍රව්‍ය අවිධිමත් ලෙස බැහැර කිරීමෙන් නිපදවන වායුය.', 'නාගරික ඝන අපද්‍රව්‍ය අවිධිමත් ලෙස බැහැර කිරීමෙන් නිපදවන වායුය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('04b03131-9592-4751-a379-46139bf186e3', '7573f0f3-b796-540f-878b-912ca5fd1b1c', 'ජෛව ඉන්ධන දහනය කරන වාහන වලින් පිටවන අපවාතයයි.', 'ජෛව ඉන්ධන දහනය කරන වාහන වලින් පිටවන අපවාතයයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('15cb95a6-62b9-505e-86e1-eea6d4727019', '3606931e-d7be-5c30-a36e-e29533680455', 26, '<p>ලිතියම් ($Li$) මූල ද්‍රව්‍යය හා එහි සංයෝග සම්බන්ධව පහත සඳහන් කුමන ප්‍රකාශය වැරදි වේද?</p>', '<p>ලිතියම් ($Li$) මූල ද්‍රව්‍යය හා එහි සංයෝග සම්බන්ධව පහත සඳහන් කුමන ප්‍රකාශය වැරදි වේද?</p>', NULL, 'ලිතියම් පරමාණුවේ අරය පළමු කාණ්ඩයේ අනෙකුත් මූලද්‍රව්‍යවලට වඩා කුඩා බැවින් එහි න්‍යෂ්ටිය සහ විස්ථානගත ඉලෙක්ට්‍රෝන අතර ආකර්ෂණය ප්‍රබල වේ. එබැවින් පළමු කාණ්ඩයේ මූලද්‍රව්‍ය අතුරෙන් ප්‍රබලතම ලෝහක බන්ධන පවතින්නේ ලිතියම් වලටය. 4 වන ප්‍රකාශය වැරදිය.', 'ලිතියම් පරමාණුවේ අරය පළමු කාණ්ඩයේ අනෙකුත් මූලද්‍රව්‍යවලට වඩා කුඩා බැවින් එහි න්‍යෂ්ටිය සහ විස්ථානගත ඉලෙක්ට්‍රෝන අතර ආකර්ෂණය ප්‍රබල වේ. එබැවින් පළමු කාණ්ඩයේ මූලද්‍රව්‍ය අතුරෙන් ප්‍රබලතම ලෝහක බන්ධන පවතින්නේ ලිතියම් වලටය. 4 වන ප්‍රකාශය වැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fd5dfd63-ad90-438b-ab18-4c1e98263bed', '15cb95a6-62b9-505e-86e1-eea6d4727019', '$Li - Cs$ දක්වා පළමු කාණ්ඩයේ මූලද්‍රව්‍ය අතුරෙන් ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය සඳහා වඩාත්ම ඍණ අගය ඇත්තේ ලිතියම්වලට ය.', '$Li - Cs$ දක්වා පළමු කාණ්ඩයේ මූලද්‍රව්‍ය අතුරෙන් ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය සඳහා වඩාත්ම ඍණ අගය ඇත්තේ ලිතියම්වලට ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('84a4d9dd-ca10-4d8a-9d32-af353fcfac82', '15cb95a6-62b9-505e-86e1-eea6d4727019', 'වාතයේ රත් කළ විට ලිතියම් ඵල දෙකක් සාදයි.', 'වාතයේ රත් කළ විට ලිතියම් ඵල දෙකක් සාදයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f132f216-b7c0-41f5-af4d-b6d0976e31aa', '15cb95a6-62b9-505e-86e1-eea6d4727019', 'පිටවන වායු සැලකූ විට, රත් කිරීමේදී $LiNO_3(s)$ වායුන් දෙකක් නිපදවන අතර $Li_2CO_3(s)$ එක් වායුවක් පමණක් ලබා දෙයි.', 'පිටවන වායු සැලකූ විට, රත් කිරීමේදී $LiNO_3(s)$ වායුන් දෙකක් නිපදවන අතර $Li_2CO_3(s)$ එක් වායුවක් පමණක් ලබා දෙයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3431f284-7f44-475f-b2c4-8294a8f5ca29', '15cb95a6-62b9-505e-86e1-eea6d4727019', 'පළමු කාණ්ඩයේ මූලද්‍රව්‍ය අතුරෙන් දුර්වලම ලෝහක බන්ධන ඇත්තේ ලිතියම් වලට ය.', 'පළමු කාණ්ඩයේ මූලද්‍රව්‍ය අතුරෙන් දුර්වලම ලෝහක බන්ධන ඇත්තේ ලිතියම් වලට ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('786ed8bb-ad96-4b7f-b178-0cad47ffd5ac', '15cb95a6-62b9-505e-86e1-eea6d4727019', 'පහන්සිළු පරීක්ෂාවේදී ලිතියම් රතු පැහැති දැල්ලක් ලබාදෙයි.', 'පහන්සිළු පරීක්ෂාවේදී ලිතියම් රතු පැහැති දැල්ලක් ලබාදෙයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b7a3dbdb-df76-50aa-a820-55aa233e0f0f', '3606931e-d7be-5c30-a36e-e29533680455', 27, '<p>ආම්ලික මාධ්‍යයේදී $Fe(NO_2)_2$ එක් මවුලයක් සමග සම්පුර්ණයෙන් ප්‍රතික්‍රියා කිරීම සඳහා අවශ්‍ය $KMnO_4$ මවුල සංඛ්‍යාව වනුයේ,<br><br>(සැ.යු. : ආම්ලික තත්ත්ව හේතුවෙන් සිදුවන $NO_2^-$ හි අඩුවීම නොසලකා හරින්න.)</p>', '<p>ආම්ලික මාධ්‍යයේදී $Fe(NO_2)_2$ එක් මවුලයක් සමග සම්පුර්ණයෙන් ප්‍රතික්‍රියා කිරීම සඳහා අවශ්‍ය $KMnO_4$ මවුල සංඛ්‍යාව වනුයේ,<br><br>(සැ.යු. : ආම්ලික තත්ත්ව හේතුවෙන් සිදුවන $NO_2^-$ හි අඩුවීම නොසලකා හරින්න.)</p>', NULL, '$Fe(NO_2)_2$ හි පවතින $Fe^{2+}$ අයනයක් $Fe^{3+}$ බවට ඔක්සිකරණය වී ඉලෙක්ට්‍රෝන 1ක් ද, $NO_2^-$ අයන 2ක් $NO_3^-$ බවට ඔක්සිකරණය වී ඉලෙක්ට්‍රෝන 4ක් ද මුදා හරී. එනම් 1 මවුලයකින් මුළු ඉලෙක්ට්‍රෝන 5ක් මුදා හැරේ.<br>ආම්ලික මාධ්‍යයේදී $KMnO_4$ හි එක් මවුලයක් ඉලෙක්ට්‍රෝන 5ක් ලබාගනී ($MnO_4^- + 8H^+ + 5e^- \rightarrow Mn^{2+} + 4H_2O$). එබැවින් ප්‍රතික්‍රියාවට හරියටම $KMnO_4$ 1 මවුලයක් අවශ්‍ය වේ.', '$Fe(NO_2)_2$ හි පවතින $Fe^{2+}$ අයනයක් $Fe^{3+}$ බවට ඔක්සිකරණය වී ඉලෙක්ට්‍රෝන 1ක් ද, $NO_2^-$ අයන 2ක් $NO_3^-$ බවට ඔක්සිකරණය වී ඉලෙක්ට්‍රෝන 4ක් ද මුදා හරී. එනම් 1 මවුලයකින් මුළු ඉලෙක්ට්‍රෝන 5ක් මුදා හැරේ.<br>ආම්ලික මාධ්‍යයේදී $KMnO_4$ හි එක් මවුලයක් ඉලෙක්ට්‍රෝන 5ක් ලබාගනී ($MnO_4^- + 8H^+ + 5e^- \rightarrow Mn^{2+} + 4H_2O$). එබැවින් ප්‍රතික්‍රියාවට හරියටම $KMnO_4$ 1 මවුලයක් අවශ්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
