INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d807bfe1-06ff-5ef8-be91-be7fde5a1895', '3606931e-d7be-5c30-a36e-e29533680455', 28, '<p>දී ඇති උෂ්ණත්වයකදී ජලය හා ජලීය ද්‍රාවණ සම්බන්ධයෙන් පහත දී ඇති කුමන වගන්තිය නිවැරදිද?</p>', '<p>දී ඇති උෂ්ණත්වයකදී ජලය හා ජලීය ද්‍රාවණ සම්බන්ධයෙන් පහත දී ඇති කුමන වගන්තිය නිවැරදිද?</p>', NULL, 'හෙන්රි නියමයට (Henry''s Law) අනුව, නියත උෂ්ණත්වයකදී දෙන ලද ද්‍රාවක පරිමාවක දියවන වායුවක ප්‍රමාණය (ද්‍රාව්‍යතාව) එම වායුව මගින් ද්‍රාවණය මතුපිට ඇති කරන ආංශික පීඩනයට අනුලෝමව සමානුපාතික වේ.', 'හෙන්රි නියමයට (Henry''s Law) අනුව, නියත උෂ්ණත්වයකදී දෙන ලද ද්‍රාවක පරිමාවක දියවන වායුවක ප්‍රමාණය (ද්‍රාව්‍යතාව) එම වායුව මගින් ද්‍රාවණය මතුපිට ඇති කරන ආංශික පීඩනයට අනුලෝමව සමානුපාතික වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('68a79536-4270-4958-9dc8-a28479f27e24', 'd807bfe1-06ff-5ef8-be91-be7fde5a1895', 'ධ්‍රැවීය වායුවක ජලයේ ද්‍රාව්‍යතාව නිර්ධ්‍රැවීය වායුවක ජලයේ ද්‍රාව්‍යතාවට වඩා අඩු වේ.', 'ධ්‍රැවීය වායුවක ජලයේ ද්‍රාව්‍යතාව නිර්ධ්‍රැවීය වායුවක ජලයේ ද්‍රාව්‍යතාවට වඩා අඩු වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f9908f03-f93f-4c9b-9d6f-45067450baa2', 'd807bfe1-06ff-5ef8-be91-be7fde5a1895', 'ඕනෑම වායුවක් ජලීය ද්‍රාවණයකදී අයනීකරණයට භාජනය වේ.', 'ඕනෑම වායුවක් ජලීය ද්‍රාවණයකදී අයනීකරණයට භාජනය වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('661b036c-65a0-4254-a86f-ca212027331a', 'd807bfe1-06ff-5ef8-be91-be7fde5a1895', 'වායුවක ජලයෙහි ද්‍රාව්‍යතාව එහි පීඩනයට සමානුපාතික වේ.', 'වායුවක ජලයෙහි ද්‍රාව්‍යතාව එහි පීඩනයට සමානුපාතික වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9ef974b2-5213-4178-83bf-e41bf3110e80', 'd807bfe1-06ff-5ef8-be91-be7fde5a1895', 'පීඩනය වැඩිවීම සමග ජලයේ තාපාංකය අඩු වේ.', 'පීඩනය වැඩිවීම සමග ජලයේ තාපාංකය අඩු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('72d5ee44-3bb5-4c40-b2cc-d99f0afe7ede', 'd807bfe1-06ff-5ef8-be91-be7fde5a1895', 'පීඩනය වැඩිවීම සමග ජලයේ ත්‍රික ලක්ෂ්‍යයේ උෂ්ණත්වය වැඩි වේ.', 'පීඩනය වැඩිවීම සමග ජලයේ ත්‍රික ලක්ෂ්‍යයේ උෂ්ණත්වය වැඩි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1a29218c-9d4d-53b4-bc2d-f7a208f0629c', '3606931e-d7be-5c30-a36e-e29533680455', 29, '<p>ක්‍රෝමියම් ($Cr$) හා එහි සංයෝග සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>ක්‍රෝමියම් ($Cr$) හා එහි සංයෝග සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, '$Cr^{2+}$ අයනය වැඩිපුර $NaOH$ සමඟ ප්‍රතික්‍රියා කර $[Cr(OH)_6]^{3-}$ සංකීර්ණය සාදයි. එය භාස්මික මාධ්‍යයේදී $H_2O_2$ මගින් ක්‍රෝමේට් ($CrO_4^{2-}$) බවට ඔක්සිකරණය වේ. ක්‍රෝමේට් අයන ද්‍රාවණය කහ පැහැති වේ.', '$Cr^{2+}$ අයනය වැඩිපුර $NaOH$ සමඟ ප්‍රතික්‍රියා කර $[Cr(OH)_6]^{3-}$ සංකීර්ණය සාදයි. එය භාස්මික මාධ්‍යයේදී $H_2O_2$ මගින් ක්‍රෝමේට් ($CrO_4^{2-}$) බවට ඔක්සිකරණය වේ. ක්‍රෝමේට් අයන ද්‍රාවණය කහ පැහැති වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('666612d7-8314-4b48-9719-5dca4f1cf940', '1a29218c-9d4d-53b4-bc2d-f7a208f0629c', '$K_2CrO_4$ ජලීය ද්‍රාවණයක් තනුක $H_2SO_4$ සමග පිරියම් කළ විට වර්ණයේ වෙනසක් නිරීක්ෂණය නොවේ.', '$K_2CrO_4$ ජලීය ද්‍රාවණයක් තනුක $H_2SO_4$ සමග පිරියම් කළ විට වර්ණයේ වෙනසක් නිරීක්ෂණය නොවේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7ee3aa42-fd22-4299-8f9a-ad4d4350fe4c', '1a29218c-9d4d-53b4-bc2d-f7a208f0629c', '$Cr$ හි විද්‍යුත් ඍණතාව $Co$ වල විද්‍යුත් සෘණතාවට වඩා විශාල වේ.', '$Cr$ හි විද්‍යුත් ඍණතාව $Co$ වල විද්‍යුත් සෘණතාවට වඩා විශාල වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1d39090c-ae6f-47dd-9458-274ae58e63c4', '1a29218c-9d4d-53b4-bc2d-f7a208f0629c', '$Cr(H_2O)_6^{2+}$ ජලීය ද්‍රාවණයක් වැඩිපුර $NaOH$ සමග පිරියම් කර, ඉන්පසු $H_2O_2$ එක් කළ විට කහ පැහැති ද්‍රාවණයක් ලැබේ.', '$Cr(H_2O)_6^{2+}$ ජලීය ද්‍රාවණයක් වැඩිපුර $NaOH$ සමග පිරියම් කර, ඉන්පසු $H_2O_2$ එක් කළ විට කහ පැහැති ද්‍රාවණයක් ලැබේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('11a1ec0b-e148-490a-b3fa-ce33b7cf2796', '1a29218c-9d4d-53b4-bc2d-f7a208f0629c', '$Cr_2O_3$ භාස්මික ලක්ෂණ පෙන්වයි.', '$Cr_2O_3$ භාස්මික ලක්ෂණ පෙන්වයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d5183bd5-c759-4cfc-a572-a67f12517d3c', '1a29218c-9d4d-53b4-bc2d-f7a208f0629c', 'ආම්ලික $K_2Cr_2O_7$ ද්‍රාවණයට $H_2S$ වායුව යැවූ විට පැහැදිලි කොළ පාට ද්‍රාවණයක් නිරීක්ෂණය වේ.', 'ආම්ලික $K_2Cr_2O_7$ ද්‍රාවණයට $H_2S$ වායුව යැවූ විට පැහැදිලි කොළ පාට ද්‍රාවණයක් නිරීක්ෂණය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('27d95802-cc42-5977-8462-27fe46461ce0', '3606931e-d7be-5c30-a36e-e29533680455', 30, '<p>පහත දැක්වෙන ප්‍රකාශ අතුරෙන් කාබොක්සිලික් අම්ල පිළිබඳව වැරදි වන්නේ කුමක්ද?</p>', '<p>පහත දැක්වෙන ප්‍රකාශ අතුරෙන් කාබොක්සිලික් අම්ල පිළිබඳව වැරදි වන්නේ කුමක්ද?</p>', NULL, 'කාබොක්සිලික් අම්ල $NaOH$ වැනි ප්‍රබල භෂ්ම සමඟ ප්‍රතික්‍රියා කර ලවණය සහ ජලය පමණක් සාදයි (උදා: $RCOOH + NaOH \rightarrow RCOONa + H_2O$). මෙහිදී කාබන්ඩයොක්සයිඩ් ($CO_2$) වායුව මුක්ත නොවේ. $CO_2$ පිටවන්නේ $Na_2CO_3$ හෝ $NaHCO_3$ සමග ප්‍රතික්‍රියා කිරීමේදීය.', 'කාබොක්සිලික් අම්ල $NaOH$ වැනි ප්‍රබල භෂ්ම සමඟ ප්‍රතික්‍රියා කර ලවණය සහ ජලය පමණක් සාදයි (උදා: $RCOOH + NaOH \rightarrow RCOONa + H_2O$). මෙහිදී කාබන්ඩයොක්සයිඩ් ($CO_2$) වායුව මුක්ත නොවේ. $CO_2$ පිටවන්නේ $Na_2CO_3$ හෝ $NaHCO_3$ සමග ප්‍රතික්‍රියා කිරීමේදීය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e51fe49b-808e-4aaf-8cfd-b285e10d6da6', '27d95802-cc42-5977-8462-27fe46461ce0', 'කාබොක්සිලික් අම්ලයක් $LiAlH_4$ සමග ප්‍රතික්‍රියා කර ලබාදෙන ඵලය ජලවිච්ඡේදනය කිරීමෙන් ඇල්කොහොලයක් ලබාදෙයි.', 'කාබොක්සිලික් අම්ලයක් $LiAlH_4$ සමග ප්‍රතික්‍රියා කර ලබාදෙන ඵලය ජලවිච්ඡේදනය කිරීමෙන් ඇල්කොහොලයක් ලබාදෙයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('26c3940a-9d19-450f-93f2-29ad20699b88', '27d95802-cc42-5977-8462-27fe46461ce0', 'ජලීය $NaOH$ සමග කාබොක්සිලික් අම්ල ප්‍රතික්‍රියා කරවූ විට කාබන්ඩයොක්සයිඩ් මුක්ත වේ.', 'ජලීය $NaOH$ සමග කාබොක්සිලික් අම්ල ප්‍රතික්‍රියා කරවූ විට කාබන්ඩයොක්සයිඩ් මුක්ත වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('28675191-b9e1-4756-8cf5-1b54db55af36', '27d95802-cc42-5977-8462-27fe46461ce0', 'කාබොක්සිලික් අම්ල $PCl_5$ සමග ප්‍රතික්‍රියා කර අම්ල ක්ලෝරයිඩ ලබා දෙයි.', 'කාබොක්සිලික් අම්ල $PCl_5$ සමග ප්‍රතික්‍රියා කර අම්ල ක්ලෝරයිඩ ලබා දෙයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2df2d8d7-2295-43af-b2c2-f3b14ef8f921', '27d95802-cc42-5977-8462-27fe46461ce0', '$CH_3MgBr$ සමග කාබොක්සිලික් අම්ල ප්‍රතික්‍රියා කරවූ විට මීතේන් මුක්ත වේ.', '$CH_3MgBr$ සමග කාබොක්සිලික් අම්ල ප්‍රතික්‍රියා කරවූ විට මීතේන් මුක්ත වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a829a8e-7753-45ea-8bd9-811bce369ef9', '27d95802-cc42-5977-8462-27fe46461ce0', 'ඇල්ඩිහයිඩ, $H^+ / K_2Cr_2O_7$ සමග පිරියම් කළ විට කාබොක්සිලික් අම්ල සෑදේ.', 'ඇල්ඩිහයිඩ, $H^+ / K_2Cr_2O_7$ සමග පිරියම් කළ විට කාබොක්සිලික් අම්ල සෑදේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('df5a1687-136f-555e-a7d9-5dfbadd201f8', '3606931e-d7be-5c30-a36e-e29533680455', 31, '<p>$HBr$ සමග ප්‍රතික්‍රියා කළ විට, 3-bromo-3-methylhexane ප්‍රධාන ඵලය ලෙස ලබාදෙන්නේ පහත දැක්වෙන ඒවායින් කුමක්/ කුමන ඒවා ද?<br><br>(a) $CH_3CH_2CH_2C(CH_3)=CHCH_3$<br>(b) $CH_3CH_2CH_2CH(CH_3)CH=CH_2$<br>(c) $CH_3CH=CHCH(CH_3)CH_2CH_3$<br>(d) $CH_3CH_2CH_2C(CH_2CH_3)=CH_2$</p>', '<p>$HBr$ සමග ප්‍රතික්‍රියා කළ විට, 3-bromo-3-methylhexane ප්‍රධාන ඵලය ලෙස ලබාදෙන්නේ පහත දැක්වෙන ඒවායින් කුමක්/ කුමන ඒවා ද?<br><br>(a) $CH_3CH_2CH_2C(CH_3)=CHCH_3$<br>(b) $CH_3CH_2CH_2CH(CH_3)CH=CH_2$<br>(c) $CH_3CH=CHCH(CH_3)CH_2CH_3$<br>(d) $CH_3CH_2CH_2C(CH_2CH_3)=CH_2$</p>', NULL, 'මාර්කොව්නිකොව් ආකලනයට අනුව ඇල්කීනයකට $HBr$ එකතු වීමේදී වඩාත් ස්ථායී කාබෝකැටායනය හරහා ප්‍රතික්‍රියාව සිදුවේ. (a) සහ (d) සංයෝගවල $H^+$ එකතු වීමෙන් සෑදෙන ස්ථායීතම කාබෝකැටායනය තෘතියික (tertiary) වන අතර, එයට $Br^-$ සම්බන්ධ වීමෙන් ප්‍රධාන ඵලය ලෙස 3-bromo-3-methylhexane ලැබේ.', 'මාර්කොව්නිකොව් ආකලනයට අනුව ඇල්කීනයකට $HBr$ එකතු වීමේදී වඩාත් ස්ථායී කාබෝකැටායනය හරහා ප්‍රතික්‍රියාව සිදුවේ. (a) සහ (d) සංයෝගවල $H^+$ එකතු වීමෙන් සෑදෙන ස්ථායීතම කාබෝකැටායනය තෘතියික (tertiary) වන අතර, එයට $Br^-$ සම්බන්ධ වීමෙන් ප්‍රධාන ඵලය ලෙස 3-bromo-3-methylhexane ලැබේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
