INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5562af5c-875e-426b-a0d7-06db6c60ffac', '9e02f00a-6ed2-5680-a140-0a3855b96369', 'වෙනත් ප්‍රතිචාර සංඛ්‍යාවක් හෝ සංයෝජනයක් හෝ නිවැරදියි', 'වෙනත් ප්‍රතිචාර සංඛ්‍යාවක් හෝ සංයෝජනයක් හෝ නිවැරදියි', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('09404c9b-d6bb-5650-a9d4-c31989b594d5', '3606931e-d7be-5c30-a36e-e29533680455', 34, '<p>ජලීය $Na_2CO_3$ සමග පිරියම් කළ විට $CO_2$ ලබා දෙන්නේ පහත දැක්වෙන ඒවායින් කුමක්/ කුමන ඒවා ද?<br><br>(a) 3-methylphenol<br>(b) phenol<br>(c) 2-phenylethanoic acid<br>(d) 3-nitrobenzoic acid</p>', '<p>ජලීය $Na_2CO_3$ සමග පිරියම් කළ විට $CO_2$ ලබා දෙන්නේ පහත දැක්වෙන ඒවායින් කුමක්/ කුමන ඒවා ද?<br><br>(a) 3-methylphenol<br>(b) phenol<br>(c) 2-phenylethanoic acid<br>(d) 3-nitrobenzoic acid</p>', NULL, 'කාබෝනික් අම්ලයට වඩා ප්‍රබල අම්ල ($pKa < 6.4$) මගින් $Na_2CO_3$ වෙතින් $CO_2$ වායුව මුක්ත කරයි. කාබොක්සිලික් අම්ල කාණ්ඩයක් සහිත සංයෝග (c) සහ ප්‍රබල ඉලෙක්ට්‍රෝන ආකර්ෂණ කාණ්ඩ සහිත ෆීනෝලීය සංයෝග (d හි 2,4-dinitrophenol) මෙලෙස ප්‍රතික්‍රියා කරයි.', 'කාබෝනික් අම්ලයට වඩා ප්‍රබල අම්ල ($pKa < 6.4$) මගින් $Na_2CO_3$ වෙතින් $CO_2$ වායුව මුක්ත කරයි. කාබොක්සිලික් අම්ල කාණ්ඩයක් සහිත සංයෝග (c) සහ ප්‍රබල ඉලෙක්ට්‍රෝන ආකර්ෂණ කාණ්ඩ සහිත ෆීනෝලීය සංයෝග (d හි 2,4-dinitrophenol) මෙලෙස ප්‍රතික්‍රියා කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
