INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('50380318-0dbc-4f0c-a73c-f353e9f25cf1', '81e1eb26-8243-54c1-bfb9-377850d85fb7', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය ද අසත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය ද අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d2601afd-40f7-5229-8e3a-11827229862b', '3606931e-d7be-5c30-a36e-e29533680455', 42, '<p>පහත සඳහන් ප්‍රකාශ යුගලය සලකා බලන්න.<br><br>පළමු ප්‍රකාශය: ඒකලිත පද්ධතියක (isolated system) අභ්‍යන්තර ශක්තිය සැමවිටම නියතව පවතී.<br>දෙවන ප්‍රකාශය: ඒකලිත පද්ධතියක් සහ එහි වටපිටාව අතර ස්කන්ධය හෝ තාපය/ශක්තිය හුවමාරු වීමක් සිදු නොවේ.</p>', '<p>පහත සඳහන් ප්‍රකාශ යුගලය සලකා බලන්න.<br><br>පළමු ප්‍රකාශය: ඒකලිත පද්ධතියක (isolated system) අභ්‍යන්තර ශක්තිය සැමවිටම නියතව පවතී.<br>දෙවන ප්‍රකාශය: ඒකලිත පද්ධතියක් සහ එහි වටපිටාව අතර ස්කන්ධය හෝ තාපය/ශක්තිය හුවමාරු වීමක් සිදු නොවේ.</p>', NULL, 'ඒකලිත පද්ධතියක් යනු වටපිටාව සමග ස්කන්ධය මෙන්ම ශක්තිය (තාපය හෝ කාර්යය ලෙස) ද හුවමාරු නොකරන පද්ධතියකි. ශක්ති හුවමාරුවක් නොවන බැවින්, තාපගති විද්‍යාවේ පළමු නියමයට අනුව එහි මුළු අභ්‍යන්තර ශක්තිය නියතව පවතී.', 'ඒකලිත පද්ධතියක් යනු වටපිටාව සමග ස්කන්ධය මෙන්ම ශක්තිය (තාපය හෝ කාර්යය ලෙස) ද හුවමාරු නොකරන පද්ධතියකි. ශක්ති හුවමාරුවක් නොවන බැවින්, තාපගති විද්‍යාවේ පළමු නියමයට අනුව එහි මුළු අභ්‍යන්තර ශක්තිය නියතව පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2993acea-de27-4cde-91d6-ddd217c8dcc9', 'd2601afd-40f7-5229-8e3a-11827229862b', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. තවද, දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. තවද, දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7673e1f1-bbe7-4cd2-857d-cf887484f4a9', 'd2601afd-40f7-5229-8e3a-11827229862b', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත්, දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත්, දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', NULL, 'sanitized', 'v1', 1, 0);
