INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3b3918ad-4eb2-4bba-abcd-3208f9d63bfe', 'c21822e8-96a9-504c-96f1-6ced24de305c', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d9723868-b8d5-4341-a14b-d9c1d7e12250', 'c21822e8-96a9-504c-96f1-6ced24de305c', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය ද අසත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය ද අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d79d151a-cef2-5c1f-97db-8d3f6fa61bdb', '3606931e-d7be-5c30-a36e-e29533680455', 50, '<p>පහත සඳහන් ප්‍රකාශ යුගලය සලකා බලන්න.<br><br>පළමු ප්‍රකාශය: ස්තරගෝලයේ (stratosphere) දී පාරජම්බුල කිරණ (UV) මගින් ඔක්සිජන් අණු වියෝජනය වීමෙන් ඕසෝන් ($O_3$) සෑදීමේ මූලික පියවර ආරම්භ වේ.<br>දෙවන ප්‍රකාශය: පරිවර්තීගෝලයේ (troposphere) ඇති ඕසෝන් වායුව මිනිසාගේ සෞඛ්‍යයට හිතකර බලපෑමක් ඇති කරයි.</p>', '<p>පහත සඳහන් ප්‍රකාශ යුගලය සලකා බලන්න.<br><br>පළමු ප්‍රකාශය: ස්තරගෝලයේ (stratosphere) දී පාරජම්බුල කිරණ (UV) මගින් ඔක්සිජන් අණු වියෝජනය වීමෙන් ඕසෝන් ($O_3$) සෑදීමේ මූලික පියවර ආරම්භ වේ.<br>දෙවන ප්‍රකාශය: පරිවර්තීගෝලයේ (troposphere) ඇති ඕසෝන් වායුව මිනිසාගේ සෞඛ්‍යයට හිතකර බලපෑමක් ඇති කරයි.</p>', NULL, 'ස්තරගෝලයේ ඇති ඔක්සිජන් අණු $UV$ කිරණ මගින් ඔක්සිජන් මුක්ත ඛණ්ඩක බවට වියෝජනය වීම ඕසෝන් සෑදීමේ පළමු පියවරයි. නමුත්, පෘථිවි පෘෂ්ඨයට ආසන්නව හෙවත් පරිවර්තීගෝලයේ (troposphere) පවතින ඕසෝන් යනු ප්‍රකාශ රසායනික ධූමිකාවට දායක වන, ශ්වසන අපහසුතා ඇති කරන දූෂක වායුවකි. එබැවින් එය සෞඛ්‍යයට අහිතකර ය. දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'ස්තරගෝලයේ ඇති ඔක්සිජන් අණු $UV$ කිරණ මගින් ඔක්සිජන් මුක්ත ඛණ්ඩක බවට වියෝජනය වීම ඕසෝන් සෑදීමේ පළමු පියවරයි. නමුත්, පෘථිවි පෘෂ්ඨයට ආසන්නව හෙවත් පරිවර්තීගෝලයේ (troposphere) පවතින ඕසෝන් යනු ප්‍රකාශ රසායනික ධූමිකාවට දායක වන, ශ්වසන අපහසුතා ඇති කරන දූෂක වායුවකි. එබැවින් එය සෞඛ්‍යයට අහිතකර ය. දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bc0d07b7-40d6-4d44-83c9-390733dd5bbf', 'd79d151a-cef2-5c1f-97db-8d3f6fa61bdb', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. තවද, දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. තවද, දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('94c18f9e-f3b6-445a-9157-72c427fedd72', 'd79d151a-cef2-5c1f-97db-8d3f6fa61bdb', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත්, දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත්, දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0b77e872-21f1-4a0e-8edb-b918dbb4c3d8', 'd79d151a-cef2-5c1f-97db-8d3f6fa61bdb', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'පළමු ප්‍රකාශය සත්‍ය වන අතර, දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('408469ff-6407-46d8-8732-5951335e010d', 'd79d151a-cef2-5c1f-97db-8d3f6fa61bdb', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය සත්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('15a550f4-578f-49cf-bede-d668b4a9b2b3', 'd79d151a-cef2-5c1f-97db-8d3f6fa61bdb', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය ද අසත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වන අතර, දෙවන ප්‍රකාශය ද අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('43383531-8f89-58cc-939b-9499b9aa4794', '379a0dba-8ada-57f5-afa2-30592bd72dc3', 1, '<p>එක් වර ම සභාව මීයට පිම්බාස් මෙන් විය.</p>', '<p>එක් වර ම සභාව මීයට පිම්බාස් මෙන් විය.</p>', NULL, '''මීයට පිම්බාක් මෙන්'' යනු ප්‍රස්තාව පිරුළක් වන අතර ඉන් අදහස් වන්නේ කිසිදු ශබ්දයක් නොමැතිව සම්පූර්ණයෙන්ම නිහඬ වීමයි.', '''මීයට පිම්බාක් මෙන්'' යනු ප්‍රස්තාව පිරුළක් වන අතර ඉන් අදහස් වන්නේ කිසිදු ශබ්දයක් නොමැතිව සම්පූර්ණයෙන්ම නිහඬ වීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cad074d4-6518-4e92-ba2b-af7d01876d75', '43383531-8f89-58cc-939b-9499b9aa4794', 'තැනින් තැනින් ඉතා සුළු ශබ්ද මතු වූවාක් මෙන්', 'තැනින් තැනින් ඉතා සුළු ශබ්ද මතු වූවාක් මෙන්', NULL, 'sanitized', 'v1', 0, 1);
