INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2c28684b-08c4-5401-bc7c-e670f6238036', '379a0dba-8ada-57f5-afa2-30592bd72dc3', 6, '<p>''ඦ'' යන අක්ෂරය සිංහල භාෂාවෙහි ...<br><br>හිස් තැනට වඩාත් සුදුසු පදය තෝරන්න.</p>', '<p>''ඦ'' යන අක්ෂරය සිංහල භාෂාවෙහි ...<br><br>හිස් තැනට වඩාත් සුදුසු පදය තෝරන්න.</p>', NULL, '''ඦ'' (සඤ්ඤක ජ) අක්ෂරය සිංහල හෝඩියේ අන්තර්ගත වුවද, එය වර්තමාන සිංහල භාෂා ව්‍යවහාරයේ භාවිත වන්නේ ඉතා දුර්ලභ (විරල) වශයෙනි.', '''ඦ'' (සඤ්ඤක ජ) අක්ෂරය සිංහල හෝඩියේ අන්තර්ගත වුවද, එය වර්තමාන සිංහල භාෂා ව්‍යවහාරයේ භාවිත වන්නේ ඉතා දුර්ලභ (විරල) වශයෙනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
