INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a92031ef-1d2a-4b9d-9da2-ec10e5c17bf0', '8908b81b-3d77-5e94-aa61-3ce17e233bde', '''නුඹ'' යන්න මධ්‍යම පුරුෂ, ඒක වචන නාම පදයකි.', '''නුඹ'' යන්න මධ්‍යම පුරුෂ, ඒක වචන නාම පදයකි.', NULL, 'sanitized', 'v1', 1, 0);
