INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6d077bbd-d60f-4ed8-a8b9-a17798aadf12', 'f512f1ab-7f00-5c05-8033-80c7110347aa', 'පාඨශාලා අධ්‍යාපනයේ මුඛ්‍ය ප්‍රතිලාභ අත්කර ගනුයේ ශිෂ්‍යයන් නො ව ගුරුවරුන් ය.', 'පාඨශාලා අධ්‍යාපනයේ මුඛ්‍ය ප්‍රතිලාභ අත්කර ගනුයේ ශිෂ්‍යයන් නො ව ගුරුවරුන් ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2c3f9feb-05ff-4f5f-895f-b2c27ec78af2', 'f512f1ab-7f00-5c05-8033-80c7110347aa', 'මානව වර්ගයාගේ උන්නතිය සඳහා ප්‍රබුද්ධ මනසක් ද නිරෝගී ශරීරයක් ද අවශ්‍ය ය.', 'මානව වර්ගයාගේ උන්නතිය සඳහා ප්‍රබුද්ධ මනසක් ද නිරෝගී ශරීරයක් ද අවශ්‍ය ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7645fcc4-9d97-4c71-9243-2b1e4734511c', 'f512f1ab-7f00-5c05-8033-80c7110347aa', 'ජලභීතිකා රෝගය නිසා සුනඛයන් පමණක් මරණයට පත් වනු දැක ගත හැකි ය.', 'ජලභීතිකා රෝගය නිසා සුනඛයන් පමණක් මරණයට පත් වනු දැක ගත හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c1de14a8-b720-5e25-a5f4-f10036e06896', '379a0dba-8ada-57f5-afa2-30592bd72dc3', 26, '<p>උගතුන් නැති තැන, මඳක් ඉගෙන ගත් තැනැත්තා ද උගතකු වශයෙන් පිළිගැනෙන බව...<br><br>අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.</p>', '<p>උගතුන් නැති තැන, මඳක් ඉගෙන ගත් තැනැත්තා ද උගතකු වශයෙන් පිළිගැනෙන බව...<br><br>අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.</p>', NULL, '''ලූලා නැති වළට කණයා පණ්ඩිතයා ලු'' යන පිරුළෙන් කියවෙන්නේ දක්ෂයන් හෝ නිසි සුදුස්සන් නොමැති තැනදී සුළු දක්ෂතාවක් ඇති තැනැත්තා ප්‍රධානියා හෝ පණ්ඩිතයා බවට පත්වන බවයි.', '''ලූලා නැති වළට කණයා පණ්ඩිතයා ලු'' යන පිරුළෙන් කියවෙන්නේ දක්ෂයන් හෝ නිසි සුදුස්සන් නොමැති තැනදී සුළු දක්ෂතාවක් ඇති තැනැත්තා ප්‍රධානියා හෝ පණ්ඩිතයා බවට පත්වන බවයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
