INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e86f510-58bf-4afb-ad91-ac6b0fdab71c', 'c1de14a8-b720-5e25-a5f4-f10036e06896', 'නිවට කපුවා දැක්කම එළුවත් රැවුල පානවලු', 'නිවට කපුවා දැක්කම එළුවත් රැවුල පානවලු', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('30f761ab-73e6-57e9-a740-88772c1dd7d5', '379a0dba-8ada-57f5-afa2-30592bd72dc3', 27, '<p>සිතෙහි හටගත් කෝපය නිසි අයුරින් නොව වෙනත් ක්‍රමයකින් පිටකර හැරීම...<br><br>අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.</p>', '<p>සිතෙහි හටගත් කෝපය නිසි අයුරින් නොව වෙනත් ක්‍රමයකින් පිටකර හැරීම...<br><br>අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.</p>', NULL, '''මුවහමට තඩි බාන්නා වාගේ'' යන පිරුළෙන් අදහස් වන්නේ තමාට සෘජුවම කෝපය ප්‍රකාශ කිරීමට නොහැකි අයෙකු වෙනුවෙන් ඇති තරහ වෙනත් අහිංසක අයෙකුගෙන් හෝ වස්තුවකින් පිටකර හැරීමයි.', '''මුවහමට තඩි බාන්නා වාගේ'' යන පිරුළෙන් අදහස් වන්නේ තමාට සෘජුවම කෝපය ප්‍රකාශ කිරීමට නොහැකි අයෙකු වෙනුවෙන් ඇති තරහ වෙනත් අහිංසක අයෙකුගෙන් හෝ වස්තුවකින් පිටකර හැරීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
