INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4317781a-80c0-49c6-978f-c2da0c8ef876', 'e2ea90a2-9aac-5811-a358-a1d15e9c8e79', 'ශිෂ්‍යයා හෝ ශිෂ්‍යාව මෙවර තරගයට ඉදිරිපත් වන්නේ ය.', 'ශිෂ්‍යයා හෝ ශිෂ්‍යාව මෙවර තරගයට ඉදිරිපත් වන්නේ ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2fbb38d0-b9cd-4dbb-a18a-197ac5b77d18', 'e2ea90a2-9aac-5811-a358-a1d15e9c8e79', '''දරුව, නිවටයෙක් සේ වැඩ නො කරව'' යි තාපසයා කීය.', '''දරුව, නිවටයෙක් සේ වැඩ නො කරව'' යි තාපසයා කීය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7a94718d-93fd-5be4-9e1f-8d56ad87addc', '379a0dba-8ada-57f5-afa2-30592bd72dc3', 31, '<p>දානපතියා අසරණයන්ට සැලකුවේ පින් ...<br>... මෙහි ගැහැනු ළමයින් නවාතැන් පහසුකම් ඇත.<br>ඒ ඉඩම් වෙන්දේසිය ... නගරාධිපතිගේ ප්‍රසාදයක් නො වී ය.<br>දේශකයා සම්මන්ත්‍රණය පැවැත්වූයේ දෙමාපියන් ...<br><br>ඉහත වාක්‍ය වල හිස් තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද ?</p>', '<p>දානපතියා අසරණයන්ට සැලකුවේ පින් ...<br>... මෙහි ගැහැනු ළමයින් නවාතැන් පහසුකම් ඇත.<br>ඒ ඉඩම් වෙන්දේසිය ... නගරාධිපතිගේ ප්‍රසාදයක් නො වී ය.<br>දේශකයා සම්මන්ත්‍රණය පැවැත්වූයේ දෙමාපියන් ...<br><br>ඉහත වාක්‍ය වල හිස් තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද ?</p>', NULL, 'නිවැරදි පිළිවෙළ වනුයේ: පින් ''පිණිස'', ළමයින් ''සඳහා'', වෙන්දේසිය ''ගැන'', දෙමාපියන් ''අරබයා'' වශයෙනි.', 'නිවැරදි පිළිවෙළ වනුයේ: පින් ''පිණිස'', ළමයින් ''සඳහා'', වෙන්දේසිය ''ගැන'', දෙමාපියන් ''අරබයා'' වශයෙනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
