INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7d610015-5bf8-465c-9a13-828f1260e8c7', 'e36fd953-4b7c-5acc-9072-993a19b6ab53', 'තරුණයා සැම දිනකම සන්ධ්‍යා වේලාවෙහි සැඟවෙයි.', 'තරුණයා සැම දිනකම සන්ධ්‍යා වේලාවෙහි සැඟවෙයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a4894f36-e5b4-5988-81c5-21db626e87cf', '379a0dba-8ada-57f5-afa2-30592bd72dc3', 33, '<p>පහත දැක්වෙන ගීත ඛණ්ඩයේ අවසන් කොටස නිවැරදි ව දැක්වෙන උත්තරය තෝරන්න.<br><br>සේ පොළෝ ගැබේ නිධාන වී<br>ඇත්තේ ඒ අභීත දූ පුතුන්<br>... යෙන්<br>සංග්‍රාම භූමියේ</p>', '<p>පහත දැක්වෙන ගීත ඛණ්ඩයේ අවසන් කොටස නිවැරදි ව දැක්වෙන උත්තරය තෝරන්න.<br><br>සේ පොළෝ ගැබේ නිධාන වී<br>ඇත්තේ ඒ අභීත දූ පුතුන්<br>... යෙන්<br>සංග්‍රාම භූමියේ</p>', NULL, 'මෙය මහගම සේකරයන් විසින් රචිත ''රත්නදීප ජන්ම භූමි'' නම් ප්‍රකට ගීතයේ කොටසකි. එහි නිවැරදි පද රචනය ''ජීවිතේ පුදා හැළූ ලේ කඳයි'' යන්නයි.', 'මෙය මහගම සේකරයන් විසින් රචිත ''රත්නදීප ජන්ම භූමි'' නම් ප්‍රකට ගීතයේ කොටසකි. එහි නිවැරදි පද රචනය ''ජීවිතේ පුදා හැළූ ලේ කඳයි'' යන්නයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1ea62f89-409e-438c-a21d-53a15ff87082', 'a4894f36-e5b4-5988-81c5-21db626e87cf', 'වීරයන්ගෙ ඒ යශෝ ගීතයයි.', 'වීරයන්ගෙ ඒ යශෝ ගීතයයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('38f82bd2-35df-4167-b657-e1c6316f4fbd', 'a4894f36-e5b4-5988-81c5-21db626e87cf', 'එන්නෙ උන් හෙළූ ප්‍රාණ වායුවයි.', 'එන්නෙ උන් හෙළූ ප්‍රාණ වායුවයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4c922081-fd9b-4053-9934-0e62685a482d', 'a4894f36-e5b4-5988-81c5-21db626e87cf', 'ජීවිතේ පුදා හැළූ ලේ කඳයි.', 'ජීවිතේ පුදා හැළූ ලේ කඳයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6b9734ef-5168-4ec4-a259-ad1c0c1daa9c', 'a4894f36-e5b4-5988-81c5-21db626e87cf', 'සාර වූ උදාර වූ මාතෘ භූමියයි.', 'සාර වූ උදාර වූ මාතෘ භූමියයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9eeed2d6-c109-5e45-b26f-fa32e2db903c', '379a0dba-8ada-57f5-afa2-30592bd72dc3', 34, '<p>ශූර අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මයාවහ දක්ෂතාවන් විදහා දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ සිත විස්මයෙන් පුරවා දමමින් බස පාලනය කරයි.<br><br>ඉහත ප්‍රකාශයේ අදහස නිවැරදි ව කියැවෙන වාක්‍යය තෝරන්න.</p>', '<p>ශූර අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මයාවහ දක්ෂතාවන් විදහා දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ සිත විස්මයෙන් පුරවා දමමින් බස පාලනය කරයි.<br><br>ඉහත ප්‍රකාශයේ අදහස නිවැරදි ව කියැවෙන වාක්‍යය තෝරන්න.</p>', NULL, 'මුල් වාක්‍යයේ අදහස වන්නේ අශ්වාරෝහකයා දක්ෂතා දක්වමින් විස්මයට පත්කරන්නා සේ සාහිත්‍යකරුවාද භාෂාව මනා ලෙස හසුරුවමින් පාඨකයා විස්මයට පත් කරන බවයි. මෙය නිවැරදිව ප්‍රකාශ වන්නේ හතරවන වාක්‍යයෙනි.', 'මුල් වාක්‍යයේ අදහස වන්නේ අශ්වාරෝහකයා දක්ෂතා දක්වමින් විස්මයට පත්කරන්නා සේ සාහිත්‍යකරුවාද භාෂාව මනා ලෙස හසුරුවමින් පාඨකයා විස්මයට පත් කරන බවයි. මෙය නිවැරදිව ප්‍රකාශ වන්නේ හතරවන වාක්‍යයෙනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('43a846b2-c79c-42ae-bf45-1f25ef7ff974', '9eeed2d6-c109-5e45-b26f-fa32e2db903c', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් පුදුමය උපදවන දස්කම් දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ බස හසුරුවන්නේ විස්මය දනවන අයුරිනි.', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් පුදුමය උපදවන දස්කම් දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ බස හසුරුවන්නේ විස්මය දනවන අයුරිනි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3f97b5ce-dd26-45c2-85b5-9a805f81dbe5', '9eeed2d6-c109-5e45-b26f-fa32e2db903c', 'දක්ෂ අසරුවෙකු විස්මයෙන් යුතුව අසුන් මෙල්ල කරන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයා විස්මයට පත් කරමින් බස හසුරුවයි.', 'දක්ෂ අසරුවෙකු විස්මයෙන් යුතුව අසුන් මෙල්ල කරන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයා විස්මයට පත් කරමින් බස හසුරුවයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e928c730-ecf9-4655-b2c5-143630db8903', '9eeed2d6-c109-5e45-b26f-fa32e2db903c', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මය දනවන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද බස හසුරුවමින් පාඨකයාගේ සිත විස්මයට පත් කරයි.', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මය දනවන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද බස හසුරුවමින් පාඨකයාගේ සිත විස්මයට පත් කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cb6e25b5-829c-434d-8944-f51e5d5c639c', '9eeed2d6-c109-5e45-b26f-fa32e2db903c', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මය දනවන ලෙස දස්කම් දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ සිත විස්මයට පත් වන ආකාරයට බස හසුරුවයි.', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මය දනවන ලෙස දස්කම් දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ සිත විස්මයට පත් වන ආකාරයට බස හසුරුවයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('970902e3-f3a5-5e0d-a58d-19b03c8a3d77', '379a0dba-8ada-57f5-afa2-30592bd72dc3', 35, '<p>''ඇතැම්හු ධූලින් වැසී ගිය ඇත් රජයැ මෑතැ සවණක් ඝන බුදු රැසින් සැදී ගිය බුදුරජාණෝ යැ. ඇතැම්හු කෝපයෙන් රත් වැ ගිය යවට වැනි ඇස් ඇති ඇත් රජයැ. මෑතැ කරුණායෙන් තෙත් වැ ගිය නිල් මහනෙල් පෙති පරයන ඇස් ඇති බුදුරජාණෝ යැ....''<br><br>යනාදි වශයෙන් ඇති පාඨය අන්තර්ගත වන කෘතිය කුමක්ද?</p>', '<p>''ඇතැම්හු ධූලින් වැසී ගිය ඇත් රජයැ මෑතැ සවණක් ඝන බුදු රැසින් සැදී ගිය බුදුරජාණෝ යැ. ඇතැම්හු කෝපයෙන් රත් වැ ගිය යවට වැනි ඇස් ඇති ඇත් රජයැ. මෑතැ කරුණායෙන් තෙත් වැ ගිය නිල් මහනෙල් පෙති පරයන ඇස් ඇති බුදුරජාණෝ යැ....''<br><br>යනාදි වශයෙන් ඇති පාඨය අන්තර්ගත වන කෘතිය කුමක්ද?</p>', NULL, 'මෙම ගද්‍ය ඛණ්ඩය විද්‍යාචක්‍රවර්තීහු විසින් රචිත ''බුත්සරණ'' ග්‍රන්ථයේ නාලාගිරි දමනය (හෝ අඟුල්මල් දමනය වැනි අදාළ පරිච්ඡේදවල) එන රචනා ශෛලියකි. බුදුරජාණන් වහන්සේගේ ගුණ වර්ණනා කරන මෙවැනි දීර්ඝ වැකි බුත්සරණෙහි විශේෂිත ලක්ෂණයකි.', 'මෙම ගද්‍ය ඛණ්ඩය විද්‍යාචක්‍රවර්තීහු විසින් රචිත ''බුත්සරණ'' ග්‍රන්ථයේ නාලාගිරි දමනය (හෝ අඟුල්මල් දමනය වැනි අදාළ පරිච්ඡේදවල) එන රචනා ශෛලියකි. බුදුරජාණන් වහන්සේගේ ගුණ වර්ණනා කරන මෙවැනි දීර්ඝ වැකි බුත්සරණෙහි විශේෂිත ලක්ෂණයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
