INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5b6a49c6-cac1-5ef7-a54d-2bc47a664c75', '3a2ca876-0732-5d0d-a113-58a1803c8b4a', 24, '<p>$4x(x + 3)$ සුළු කරන්න.</p>', '<p>$4x(x + 3)$ සුළු කරන්න.</p>', NULL, '<p>වරහන් ඉවත් කළ විට $4x \cdot x + 4x \cdot 3 = 4x^2 + 12x$.</p>', '<p>වරහන් ඉවත් කළ විට $4x \cdot x + 4x \cdot 3 = 4x^2 + 12x$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
