INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2f8573ea-1c81-5842-ad43-b7d957a39a68', '3a2ca876-0732-5d0d-a113-58a1803c8b4a', 39, '<p>$4^4 \times 4^1$ සුළු කරන්න.</p>', '<p>$4^4 \times 4^1$ සුළු කරන්න.</p>', NULL, '<p>දර්ශක නීති වලට අනුව, $a^m \times a^n = a^{m+n}$. එබැවින් $4^4 \times 4^1 = 4^{4+1} = 4^5$.</p>', '<p>දර්ශක නීති වලට අනුව, $a^m \times a^n = a^{m+n}$. එබැවින් $4^4 \times 4^1 = 4^{4+1} = 4^5$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('774977a4-8940-428a-bb7a-7471963cec15', '2f8573ea-1c81-5842-ad43-b7d957a39a68', '$4^5$', '$4^5$', NULL, 'sanitized', 'v1', 0, 1);
