INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d00effd-c280-51bb-bde1-9f4328a1f6fd', '3c170885-4094-5d06-bce2-7d4da3d651d4', 1, '<p>එක් වර ම සභාව මීයට පිම්බාස් මෙන් විය.</p>', '<p>එක් වර ම සභාව මීයට පිම්බාස් මෙන් විය.</p>', NULL, '''මීයට පිම්බාක් මෙන්'' යනු ප්‍රස්තාව පිරුළක් වන අතර ඉන් අදහස් වන්නේ කිසිදු ශබ්දයක් නොමැතිව සම්පූර්ණයෙන්ම නිහඬ වීමයි.', '''මීයට පිම්බාක් මෙන්'' යනු ප්‍රස්තාව පිරුළක් වන අතර ඉන් අදහස් වන්නේ කිසිදු ශබ්දයක් නොමැතිව සම්පූර්ණයෙන්ම නිහඬ වීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5d79eb98-830c-444d-ba87-f47821ba4078', '1d00effd-c280-51bb-bde1-9f4328a1f6fd', 'තැනින් තැනින් ඉතා සුළු ශබ්ද මතු වූවාක් මෙන්', 'තැනින් තැනින් ඉතා සුළු ශබ්ද මතු වූවාක් මෙන්', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('297adc6c-0afa-4486-8e3a-174be47dcb4f', '1d00effd-c280-51bb-bde1-9f4328a1f6fd', 'කිසිදු ශබ්දයකින් තොර වූවාක් මෙන්', 'කිසිදු ශබ්දයකින් තොර වූවාක් මෙන්', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2b30ffa3-ede6-4a48-938d-1aedd4245a02', '1d00effd-c280-51bb-bde1-9f4328a1f6fd', 'කිහිප දෙනෙකු කතා කරද්දී අනික් අය නිහඬ වූවාක් මෙන්', 'කිහිප දෙනෙකු කතා කරද්දී අනික් අය නිහඬ වූවාක් මෙන්', NULL, 'sanitized', 'v1', 2, 0);
