INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2eb00b6c-e34a-46f8-935c-b85167dc13a0', 'ca4a4370-ee14-5980-91ca-3e847d5a1eaf', 'නිරන්තරයෙන්', 'නිරන්තරයෙන්', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d6d4cefc-a649-55ca-bdd6-bc84f5bbb84a', '3c170885-4094-5d06-bce2-7d4da3d651d4', 7, '<p>සැම පදයක ම අක්ෂර වින්‍යාසය නිවැරදි ව යෙදී ඇති පද පේළිය තෝරන්න.</p>', '<p>සැම පදයක ම අක්ෂර වින්‍යාසය නිවැරදි ව යෙදී ඇති පද පේළිය තෝරන්න.</p>', NULL, 'තුන්වන පිළිතුරේ ඇති ''කොළය, පර්යේෂණ, නිගණ්ඨ, සක්වළ'' යන සියලුම පද අක්ෂර වින්‍යාස නීතිවලට අනුකූලව නිවැරදිව ලියා ඇත. අනෙක් වරණවල ''මෙවුළ'' (මෙවුල විය යුතුය), ''ජේදය'' (ඡේදය විය යුතුය), ''සැණකෙලි'' (සැණකෙළි විය යුතුය) ආදී දෝෂ පවතී.', 'තුන්වන පිළිතුරේ ඇති ''කොළය, පර්යේෂණ, නිගණ්ඨ, සක්වළ'' යන සියලුම පද අක්ෂර වින්‍යාස නීතිවලට අනුකූලව නිවැරදිව ලියා ඇත. අනෙක් වරණවල ''මෙවුළ'' (මෙවුල විය යුතුය), ''ජේදය'' (ඡේදය විය යුතුය), ''සැණකෙලි'' (සැණකෙළි විය යුතුය) ආදී දෝෂ පවතී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
