INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('157a55d8-1821-4adc-8d52-9ea9f2580dfa', 'd6d4cefc-a649-55ca-bdd6-bc84f5bbb84a', 'කොළය, පර්යේෂණ, නිගණ්ඨ, සක්වළ', 'කොළය, පර්යේෂණ, නිගණ්ඨ, සක්වළ', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6bb95229-f544-4d89-9575-62f39627479e', 'd6d4cefc-a649-55ca-bdd6-bc84f5bbb84a', 'ප්‍රත්‍යක්ෂ, ආශ්චර්ය, සැණකෙලි, අනබෙරය', 'ප්‍රත්‍යක්ෂ, ආශ්චර්ය, සැණකෙලි, අනබෙරය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8c6c58c5-a877-5f04-a774-e3c83ca51673', '3c170885-4094-5d06-bce2-7d4da3d651d4', 8, '<p>ගිගිරි, කෙක්ක, කුඹියා, සාගරය යන වචන වල පළමු අකුරෙහි අන්තර්ගත පිල්ලම අනු පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', '<p>ගිගිරි, කෙක්ක, කුඹියා, සාගරය යන වචන වල පළමු අකුරෙහි අන්තර්ගත පිල්ලම අනු පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', NULL, 'ගි = ග් + ඉ (කෙටි ඉස්පිල්ල), කෙ = ක් + එ (කොම්බුව), කූ = ක් + ඌ (දිගු පාපිල්ල), සා = ස් + ආ (ඇලපිල්ල). එබැවින් නිවැරදි පිළිවෙළ 4 වේ.', 'ගි = ග් + ඉ (කෙටි ඉස්පිල්ල), කෙ = ක් + එ (කොම්බුව), කූ = ක් + ඌ (දිගු පාපිල්ල), සා = ස් + ආ (ඇලපිල්ල). එබැවින් නිවැරදි පිළිවෙළ 4 වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3955fa0a-636c-4498-900f-4aa44e949581', '8c6c58c5-a877-5f04-a774-e3c83ca51673', 'කෙටි ඉස්පිල්ල, ඇලපිල්ල, දිගු පාපිල්ල, කොම්බුව', 'කෙටි ඉස්පිල්ල, ඇලපිල්ල, දිගු පාපිල්ල, කොම්බුව', NULL, 'sanitized', 'v1', 0, 1);
