INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8502c771-01a1-48e2-8180-151994e65b37', '8c6c58c5-a877-5f04-a774-e3c83ca51673', 'කෙටි ඉස්පිල්ල, කොම්බුව, දිගු පාපිල්ල, ඇලපිල්ල', 'කෙටි ඉස්පිල්ල, කොම්බුව, දිගු පාපිල්ල, ඇලපිල්ල', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b17a7271-70fc-5a60-b633-6836575714f9', '3c170885-4094-5d06-bce2-7d4da3d651d4', 9, '<p>''තනතුර'' යන පදයෙහි අන්තර්ගත ව්‍යංජන අක්ෂර වර්ග වනුයේ.</p>', '<p>''තනතුර'' යන පදයෙහි අන්තර්ගත ව්‍යංජන අක්ෂර වර්ග වනුයේ.</p>', NULL, '''තනතුර'' පදයේ අන්තර්ගත ව්‍යංජන වන්නේ ත, න, ත, ර ය. මෙහි ත සහ න අක්ෂර දන්තජ (දත් මුල් ස්ථාන කරගත්) අකුරු වන අතර, ර අක්ෂරය මූර්ධජ (තල්ලේ මුදුන ස්ථාන කරගත්) අකුරකි.', '''තනතුර'' පදයේ අන්තර්ගත ව්‍යංජන වන්නේ ත, න, ත, ර ය. මෙහි ත සහ න අක්ෂර දන්තජ (දත් මුල් ස්ථාන කරගත්) අකුරු වන අතර, ර අක්ෂරය මූර්ධජ (තල්ලේ මුදුන ස්ථාන කරගත්) අකුරකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
