INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7a693ac1-10e3-56fc-bb38-a115d580ae19', '3c170885-4094-5d06-bce2-7d4da3d651d4', 24, '<p>වැරදි අදහස දෙන ප්‍රකාශය තෝරන්න.</p>', '<p>වැරදි අදහස දෙන ප්‍රකාශය තෝරන්න.</p>', NULL, '''නරියා'' යනු උක්ත ඒකවචන රූපයයි. ''නරියන්'' යනු අනුක්ත බහුවචන රූපයයි. එබැවින් ''නරියන් යන්නෙහි අනුක්ත රූපය නරියා යන්නයි'' යන ප්‍රකාශය සම්පූර්ණයෙන්ම ව්‍යාකරණානුකූලව වැරදිය.', '''නරියා'' යනු උක්ත ඒකවචන රූපයයි. ''නරියන්'' යනු අනුක්ත බහුවචන රූපයයි. එබැවින් ''නරියන් යන්නෙහි අනුක්ත රූපය නරියා යන්නයි'' යන ප්‍රකාශය සම්පූර්ණයෙන්ම ව්‍යාකරණානුකූලව වැරදිය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c249f0d9-406e-43e7-80b6-b2b20f659a1c', '7a693ac1-10e3-56fc-bb38-a115d580ae19', '''එම්බා'' යනු ආමන්ත්‍රණාර්ථයෙහි නිපාතයකි.', '''එම්බා'' යනු ආමන්ත්‍රණාර්ථයෙහි නිපාතයකි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aac7de27-ed06-4c9f-83a5-47850c56a037', '7a693ac1-10e3-56fc-bb38-a115d580ae19', '''නුඹ'' යන්න මධ්‍යම පුරුෂ, ඒක වචන නාම පදයකි.', '''නුඹ'' යන්න මධ්‍යම පුරුෂ, ඒක වචන නාම පදයකි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2d6fccbe-2779-4882-b52d-8b371588f3bc', '7a693ac1-10e3-56fc-bb38-a115d580ae19', '''ර, ල, ව'' යනු අන්තඃස්ථාක්ෂර ය.', '''ර, ල, ව'' යනු අන්තඃස්ථාක්ෂර ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('73f8f45e-5516-489c-bf00-21afe1903c67', '7a693ac1-10e3-56fc-bb38-a115d580ae19', '''නරියන්'' යන්නෙහි අනුක්ත රූපය ''නරියා'' යන්න යි.', '''නරියන්'' යන්නෙහි අනුක්ත රූපය ''නරියා'' යන්න යි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4b0e1ade-f8e3-5da8-9920-f5fc2d5d136e', '3c170885-4094-5d06-bce2-7d4da3d651d4', 25, '<p>පහත දැක්වෙන වාක්‍ය අතුරෙන් පද ගැළපීමෙන් යුක්ත, අර්ථාන්විත වාක්‍යය තෝරන්න.</p>', '<p>පහත දැක්වෙන වාක්‍ය අතුරෙන් පද ගැළපීමෙන් යුක්ත, අර්ථාන්විත වාක්‍යය තෝරන්න.</p>', NULL, 'තුන්වන වාක්‍යය අර්ථය අතින් පැහැදිලි මෙන්ම ව්‍යාකරණානුකූල පද ගැළපීමකින් යුක්ත වේ. අනෙක් වාක්‍ය වල තාර්කික හෝ ව්‍යාකරණමය දෝෂ පවතී.', 'තුන්වන වාක්‍යය අර්ථය අතින් පැහැදිලි මෙන්ම ව්‍යාකරණානුකූල පද ගැළපීමකින් යුක්ත වේ. අනෙක් වාක්‍ය වල තාර්කික හෝ ව්‍යාකරණමය දෝෂ පවතී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0c93cb97-4ab3-49e4-b817-300767b2516b', '4b0e1ade-f8e3-5da8-9920-f5fc2d5d136e', 'තැනිතලා, කඳු මුදුන් පසු කර යන ගංගා ජලය ආරම්භයේ දී ම සමුද්‍රයට එක් වේ.', 'තැනිතලා, කඳු මුදුන් පසු කර යන ගංගා ජලය ආරම්භයේ දී ම සමුද්‍රයට එක් වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f657fe6-7ab9-475c-a00c-a3602fa7c348', '4b0e1ade-f8e3-5da8-9920-f5fc2d5d136e', 'පාඨශාලා අධ්‍යාපනයේ මුඛ්‍ය ප්‍රතිලාභ අත්කර ගනුයේ ශිෂ්‍යයන් නො ව ගුරුවරුන් ය.', 'පාඨශාලා අධ්‍යාපනයේ මුඛ්‍ය ප්‍රතිලාභ අත්කර ගනුයේ ශිෂ්‍යයන් නො ව ගුරුවරුන් ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ee7474cc-60e0-48b9-aa53-117fe431ac00', '4b0e1ade-f8e3-5da8-9920-f5fc2d5d136e', 'මානව වර්ගයාගේ උන්නතිය සඳහා ප්‍රබුද්ධ මනසක් ද නිරෝගී ශරීරයක් ද අවශ්‍ය ය.', 'මානව වර්ගයාගේ උන්නතිය සඳහා ප්‍රබුද්ධ මනසක් ද නිරෝගී ශරීරයක් ද අවශ්‍ය ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('56ae43aa-fbde-4eb6-b1ed-3cecb433ff76', '4b0e1ade-f8e3-5da8-9920-f5fc2d5d136e', 'ජලභීතිකා රෝගය නිසා සුනඛයන් පමණක් මරණයට පත් වනු දැක ගත හැකි ය.', 'ජලභීතිකා රෝගය නිසා සුනඛයන් පමණක් මරණයට පත් වනු දැක ගත හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('528d29eb-1ee2-59a7-93c5-9f04f39f4825', '3c170885-4094-5d06-bce2-7d4da3d651d4', 26, '<p>උගතුන් නැති තැන, මඳක් ඉගෙන ගත් තැනැත්තා ද උගතකු වශයෙන් පිළිගැනෙන බව...<br><br>අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.</p>', '<p>උගතුන් නැති තැන, මඳක් ඉගෙන ගත් තැනැත්තා ද උගතකු වශයෙන් පිළිගැනෙන බව...<br><br>අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.</p>', NULL, '''ලූලා නැති වළට කණයා පණ්ඩිතයා ලු'' යන පිරුළෙන් කියවෙන්නේ දක්ෂයන් හෝ නිසි සුදුස්සන් නොමැති තැනදී සුළු දක්ෂතාවක් ඇති තැනැත්තා ප්‍රධානියා හෝ පණ්ඩිතයා බවට පත්වන බවයි.', '''ලූලා නැති වළට කණයා පණ්ඩිතයා ලු'' යන පිරුළෙන් කියවෙන්නේ දක්ෂයන් හෝ නිසි සුදුස්සන් නොමැති තැනදී සුළු දක්ෂතාවක් ඇති තැනැත්තා ප්‍රධානියා හෝ පණ්ඩිතයා බවට පත්වන බවයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
