INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bb501f55-e2c3-4ffe-9fae-de3284d8e64d', '528d29eb-1ee2-59a7-93c5-9f04f39f4825', 'නිවට කපුවා දැක්කම එළුවත් රැවුල පානවලු', 'නිවට කපුවා දැක්කම එළුවත් රැවුල පානවලු', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('eabbc1b1-3349-52ac-9777-ec2af4ef06d1', '3c170885-4094-5d06-bce2-7d4da3d651d4', 27, '<p>සිතෙහි හටගත් කෝපය නිසි අයුරින් නොව වෙනත් ක්‍රමයකින් පිටකර හැරීම...<br><br>අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.</p>', '<p>සිතෙහි හටගත් කෝපය නිසි අයුරින් නොව වෙනත් ක්‍රමයකින් පිටකර හැරීම...<br><br>අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.</p>', NULL, '''මුවහමට තඩි බාන්නා වාගේ'' යන පිරුළෙන් අදහස් වන්නේ තමාට සෘජුවම කෝපය ප්‍රකාශ කිරීමට නොහැකි අයෙකු වෙනුවෙන් ඇති තරහ වෙනත් අහිංසක අයෙකුගෙන් හෝ වස්තුවකින් පිටකර හැරීමයි.', '''මුවහමට තඩි බාන්නා වාගේ'' යන පිරුළෙන් අදහස් වන්නේ තමාට සෘජුවම කෝපය ප්‍රකාශ කිරීමට නොහැකි අයෙකු වෙනුවෙන් ඇති තරහ වෙනත් අහිංසක අයෙකුගෙන් හෝ වස්තුවකින් පිටකර හැරීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
