INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7b43db61-0ffc-491e-b93e-4d07bd973772', '9dad3023-972f-55a1-aef5-ada1d50b0934', 'නගරාධිපති බලවතෙක් ද ධනවතෙක් ද ගුණවතකු ද වූයේ ය.', 'නගරාධිපති බලවතෙක් ද ධනවතෙක් ද ගුණවතකු ද වූයේ ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('55d4b8ec-f59a-41bb-8681-343c891f630d', '9dad3023-972f-55a1-aef5-ada1d50b0934', 'ශිෂ්‍යයා හෝ ශිෂ්‍යාව මෙවර තරගයට ඉදිරිපත් වන්නේ ය.', 'ශිෂ්‍යයා හෝ ශිෂ්‍යාව මෙවර තරගයට ඉදිරිපත් වන්නේ ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ab4a62c4-09f6-4273-9f38-50c5b4c09439', '9dad3023-972f-55a1-aef5-ada1d50b0934', '''දරුව, නිවටයෙක් සේ වැඩ නො කරව'' යි තාපසයා කීය.', '''දරුව, නිවටයෙක් සේ වැඩ නො කරව'' යි තාපසයා කීය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c9571d24-9323-5607-805b-4c5df9bc5c04', '3c170885-4094-5d06-bce2-7d4da3d651d4', 31, '<p>දානපතියා අසරණයන්ට සැලකුවේ පින් ...<br>... මෙහි ගැහැනු ළමයින් නවාතැන් පහසුකම් ඇත.<br>ඒ ඉඩම් වෙන්දේසිය ... නගරාධිපතිගේ ප්‍රසාදයක් නො වී ය.<br>දේශකයා සම්මන්ත්‍රණය පැවැත්වූයේ දෙමාපියන් ...<br><br>ඉහත වාක්‍ය වල හිස් තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද ?</p>', '<p>දානපතියා අසරණයන්ට සැලකුවේ පින් ...<br>... මෙහි ගැහැනු ළමයින් නවාතැන් පහසුකම් ඇත.<br>ඒ ඉඩම් වෙන්දේසිය ... නගරාධිපතිගේ ප්‍රසාදයක් නො වී ය.<br>දේශකයා සම්මන්ත්‍රණය පැවැත්වූයේ දෙමාපියන් ...<br><br>ඉහත වාක්‍ය වල හිස් තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද ?</p>', NULL, 'නිවැරදි පිළිවෙළ වනුයේ: පින් ''පිණිස'', ළමයින් ''සඳහා'', වෙන්දේසිය ''ගැන'', දෙමාපියන් ''අරබයා'' වශයෙනි.', 'නිවැරදි පිළිවෙළ වනුයේ: පින් ''පිණිස'', ළමයින් ''සඳහා'', වෙන්දේසිය ''ගැන'', දෙමාපියන් ''අරබයා'' වශයෙනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
