INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8bf9911c-e2fd-4967-aedd-713852b719af', 'c9571d24-9323-5607-805b-4c5df9bc5c04', 'සඳහා, ගැන, පිණිස, අරබයා', 'සඳහා, ගැන, පිණිස, අරබයා', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f825c758-87f9-54b1-a538-3422ef804514', '3c170885-4094-5d06-bce2-7d4da3d651d4', 32, '<p>පහත දැක්වෙන වාක්‍යය ලේඛන ව්‍යවහාරයට හැරවූ විට වඩාත් නිවැරදි වන්නේ කුමක්ද?<br><br>''ඉලන්දාරියා හැමදාම හැන්දෑ ජාමෙට වහං වෙනවා''</p>', '<p>පහත දැක්වෙන වාක්‍යය ලේඛන ව්‍යවහාරයට හැරවූ විට වඩාත් නිවැරදි වන්නේ කුමක්ද?<br><br>''ඉලන්දාරියා හැමදාම හැන්දෑ ජාමෙට වහං වෙනවා''</p>', NULL, 'ලිඛිත ව්‍යවහාරයට හැරවීමේදී පදවල නිවැරදි සාහිත්‍යමය රූපය යෙදිය යුතුය. ''වහං වෙනවා'' යනු වර්තමාන කාල ක්‍රියාවක් බැවින් ''සැඟවෙයි'' ලෙස ලිඛිත භාෂාවෙන් නිවැරදිව යෙදේ.', 'ලිඛිත ව්‍යවහාරයට හැරවීමේදී පදවල නිවැරදි සාහිත්‍යමය රූපය යෙදිය යුතුය. ''වහං වෙනවා'' යනු වර්තමාන කාල ක්‍රියාවක් බැවින් ''සැඟවෙයි'' ලෙස ලිඛිත භාෂාවෙන් නිවැරදිව යෙදේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
