INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e87b8c20-284a-4bbf-98d8-7118f4d66152', 'f825c758-87f9-54b1-a538-3422ef804514', 'තරුණයා සැම දවසකම සන්ධ්‍යාවෙහි හැංගුණේ ය.', 'තරුණයා සැම දවසකම සන්ධ්‍යාවෙහි හැංගුණේ ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('233dabff-095d-4081-8a69-2bdd8f30d415', 'f825c758-87f9-54b1-a538-3422ef804514', 'තරුණයා සැම දිනකම සන්ධ්‍යා වේලාවෙහි සැඟවෙයි.', 'තරුණයා සැම දිනකම සන්ධ්‍යා වේලාවෙහි සැඟවෙයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b8b0ca92-1602-5069-9b4c-e0ab1308b7f6', '3c170885-4094-5d06-bce2-7d4da3d651d4', 33, '<p>පහත දැක්වෙන ගීත ඛණ්ඩයේ අවසන් කොටස නිවැරදි ව දැක්වෙන උත්තරය තෝරන්න.<br><br>සේ පොළෝ ගැබේ නිධාන වී<br>ඇත්තේ ඒ අභීත දූ පුතුන්<br>... යෙන්<br>සංග්‍රාම භූමියේ</p>', '<p>පහත දැක්වෙන ගීත ඛණ්ඩයේ අවසන් කොටස නිවැරදි ව දැක්වෙන උත්තරය තෝරන්න.<br><br>සේ පොළෝ ගැබේ නිධාන වී<br>ඇත්තේ ඒ අභීත දූ පුතුන්<br>... යෙන්<br>සංග්‍රාම භූමියේ</p>', NULL, 'මෙය මහගම සේකරයන් විසින් රචිත ''රත්නදීප ජන්ම භූමි'' නම් ප්‍රකට ගීතයේ කොටසකි. එහි නිවැරදි පද රචනය ''ජීවිතේ පුදා හැළූ ලේ කඳයි'' යන්නයි.', 'මෙය මහගම සේකරයන් විසින් රචිත ''රත්නදීප ජන්ම භූමි'' නම් ප්‍රකට ගීතයේ කොටසකි. එහි නිවැරදි පද රචනය ''ජීවිතේ පුදා හැළූ ලේ කඳයි'' යන්නයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('078099bb-da2d-4ba6-b7b6-b945da305c1d', 'b8b0ca92-1602-5069-9b4c-e0ab1308b7f6', 'වීරයන්ගෙ ඒ යශෝ ගීතයයි.', 'වීරයන්ගෙ ඒ යශෝ ගීතයයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('458258ea-723f-404b-b2b4-9a4115061d2a', 'b8b0ca92-1602-5069-9b4c-e0ab1308b7f6', 'එන්නෙ උන් හෙළූ ප්‍රාණ වායුවයි.', 'එන්නෙ උන් හෙළූ ප්‍රාණ වායුවයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9dc44cdf-6b8d-464e-92a0-c402bd536ac4', 'b8b0ca92-1602-5069-9b4c-e0ab1308b7f6', 'ජීවිතේ පුදා හැළූ ලේ කඳයි.', 'ජීවිතේ පුදා හැළූ ලේ කඳයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c1f81170-6c06-4ebe-86ef-96ad14e6c950', 'b8b0ca92-1602-5069-9b4c-e0ab1308b7f6', 'සාර වූ උදාර වූ මාතෘ භූමියයි.', 'සාර වූ උදාර වූ මාතෘ භූමියයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('06fb044c-4f9e-5209-88a9-860c341a0467', '3c170885-4094-5d06-bce2-7d4da3d651d4', 34, '<p>ශූර අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මයාවහ දක්ෂතාවන් විදහා දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ සිත විස්මයෙන් පුරවා දමමින් බස පාලනය කරයි.<br><br>ඉහත ප්‍රකාශයේ අදහස නිවැරදි ව කියැවෙන වාක්‍යය තෝරන්න.</p>', '<p>ශූර අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මයාවහ දක්ෂතාවන් විදහා දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ සිත විස්මයෙන් පුරවා දමමින් බස පාලනය කරයි.<br><br>ඉහත ප්‍රකාශයේ අදහස නිවැරදි ව කියැවෙන වාක්‍යය තෝරන්න.</p>', NULL, 'මුල් වාක්‍යයේ අදහස වන්නේ අශ්වාරෝහකයා දක්ෂතා දක්වමින් විස්මයට පත්කරන්නා සේ සාහිත්‍යකරුවාද භාෂාව මනා ලෙස හසුරුවමින් පාඨකයා විස්මයට පත් කරන බවයි. මෙය නිවැරදිව ප්‍රකාශ වන්නේ හතරවන වාක්‍යයෙනි.', 'මුල් වාක්‍යයේ අදහස වන්නේ අශ්වාරෝහකයා දක්ෂතා දක්වමින් විස්මයට පත්කරන්නා සේ සාහිත්‍යකරුවාද භාෂාව මනා ලෙස හසුරුවමින් පාඨකයා විස්මයට පත් කරන බවයි. මෙය නිවැරදිව ප්‍රකාශ වන්නේ හතරවන වාක්‍යයෙනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6d191607-93ae-4bf5-af20-a56621755afa', '06fb044c-4f9e-5209-88a9-860c341a0467', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් පුදුමය උපදවන දස්කම් දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ බස හසුරුවන්නේ විස්මය දනවන අයුරිනි.', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් පුදුමය උපදවන දස්කම් දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ බස හසුරුවන්නේ විස්මය දනවන අයුරිනි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1380ec78-341a-4156-bd37-9b11c6250845', '06fb044c-4f9e-5209-88a9-860c341a0467', 'දක්ෂ අසරුවෙකු විස්මයෙන් යුතුව අසුන් මෙල්ල කරන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයා විස්මයට පත් කරමින් බස හසුරුවයි.', 'දක්ෂ අසරුවෙකු විස්මයෙන් යුතුව අසුන් මෙල්ල කරන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයා විස්මයට පත් කරමින් බස හසුරුවයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('92c52788-ca1e-452b-87b2-b5febdbdace6', '06fb044c-4f9e-5209-88a9-860c341a0467', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මය දනවන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද බස හසුරුවමින් පාඨකයාගේ සිත විස්මයට පත් කරයි.', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මය දනවන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද බස හසුරුවමින් පාඨකයාගේ සිත විස්මයට පත් කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b9058cbb-275d-4f76-9506-30802e8567a3', '06fb044c-4f9e-5209-88a9-860c341a0467', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මය දනවන ලෙස දස්කම් දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ සිත විස්මයට පත් වන ආකාරයට බස හසුරුවයි.', 'දක්ෂ අසරුවෙකු අසුන් මෙල්ල කරමින් විස්මය දනවන ලෙස දස්කම් දක්වන්නාක් මෙන්, නිපුණ සාහිත්‍ය කරුවා ද පාඨකයාගේ සිත විස්මයට පත් වන ආකාරයට බස හසුරුවයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2972406a-2722-5a2b-a6ca-0c3b8aa6d6e6', '3c170885-4094-5d06-bce2-7d4da3d651d4', 35, '<p>''ඇතැම්හු ධූලින් වැසී ගිය ඇත් රජයැ මෑතැ සවණක් ඝන බුදු රැසින් සැදී ගිය බුදුරජාණෝ යැ. ඇතැම්හු කෝපයෙන් රත් වැ ගිය යවට වැනි ඇස් ඇති ඇත් රජයැ. මෑතැ කරුණායෙන් තෙත් වැ ගිය නිල් මහනෙල් පෙති පරයන ඇස් ඇති බුදුරජාණෝ යැ....''<br><br>යනාදි වශයෙන් ඇති පාඨය අන්තර්ගත වන කෘතිය කුමක්ද?</p>', '<p>''ඇතැම්හු ධූලින් වැසී ගිය ඇත් රජයැ මෑතැ සවණක් ඝන බුදු රැසින් සැදී ගිය බුදුරජාණෝ යැ. ඇතැම්හු කෝපයෙන් රත් වැ ගිය යවට වැනි ඇස් ඇති ඇත් රජයැ. මෑතැ කරුණායෙන් තෙත් වැ ගිය නිල් මහනෙල් පෙති පරයන ඇස් ඇති බුදුරජාණෝ යැ....''<br><br>යනාදි වශයෙන් ඇති පාඨය අන්තර්ගත වන කෘතිය කුමක්ද?</p>', NULL, 'මෙම ගද්‍ය ඛණ්ඩය විද්‍යාචක්‍රවර්තීහු විසින් රචිත ''බුත්සරණ'' ග්‍රන්ථයේ නාලාගිරි දමනය (හෝ අඟුල්මල් දමනය වැනි අදාළ පරිච්ඡේදවල) එන රචනා ශෛලියකි. බුදුරජාණන් වහන්සේගේ ගුණ වර්ණනා කරන මෙවැනි දීර්ඝ වැකි බුත්සරණෙහි විශේෂිත ලක්ෂණයකි.', 'මෙම ගද්‍ය ඛණ්ඩය විද්‍යාචක්‍රවර්තීහු විසින් රචිත ''බුත්සරණ'' ග්‍රන්ථයේ නාලාගිරි දමනය (හෝ අඟුල්මල් දමනය වැනි අදාළ පරිච්ඡේදවල) එන රචනා ශෛලියකි. බුදුරජාණන් වහන්සේගේ ගුණ වර්ණනා කරන මෙවැනි දීර්ඝ වැකි බුත්සරණෙහි විශේෂිත ලක්ෂණයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
