INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('231b267d-c0c6-5e23-a6d1-0ec0b87b1e15', '3f8797c3-499b-57d1-8b46-d764936b1b22', 6, '<p>$H_{2}N_{2}O$ අණුවේ (සැකිල්ල: $H-N^{1}-N^{2}-O$ ) නයිට්‍රජන් පරමාණු දෙක අවට ($N^{1}$ සහ $N^{2}$ ලෙස ලේබල් කර ඇත.) ඉලෙක්ට්‍රෝන යුගල් ජ්‍යාමිතිය සහ හැඩය පිළිවෙළින් වනුයේ,<br><br><br><br></p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c57dc310-0466-4448-b150-1bff86a2b805', '231b267d-c0c6-5e23-a6d1-0ec0b87b1e15', '$N^{1}$: චතුස්තලීය, පිරමිඩාකාර ; $N^{2}$: තලීය ත්‍රිකෝණාකාර, කෝණික', '$N^{1}$: චතුස්තලීය, පිරමිඩාකාර ; $N^{2}$: තලීය ත්‍රිකෝණාකාර, කෝණික', NULL, 'sanitized', 'v1', 0, 1);
