INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2174dc83-c5b6-4807-8edb-08f66adc5beb', '231b267d-c0c6-5e23-a6d1-0ec0b87b1e15', '$N^{1}$: තලීය ත්‍රිකෝණාකාර, පිරමිඩාකාර ; $N^{2}$: තලීය ත්‍රිකෝණාකාර, තලීය ත්‍රිකෝණාකාර', '$N^{1}$: තලීය ත්‍රිකෝණාකාර, පිරමිඩාකාර ; $N^{2}$: තලීය ත්‍රිකෝණාකාර, තලීය ත්‍රිකෝණාකාර', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('972d4f3d-771f-4214-ba82-9984df958250', '231b267d-c0c6-5e23-a6d1-0ec0b87b1e15', '$N^{1}$: චතුස්තලීය, පිරමිඩාකාර ; $N^{2}$: කෝණික, තලීය ත්‍රිකෝණාකාර', '$N^{1}$: චතුස්තලීය, පිරමිඩාකාර ; $N^{2}$: කෝණික, තලීය ත්‍රිකෝණාකාර', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4f9cadd9-2609-4a2e-b73d-5c9c4847869d', '231b267d-c0c6-5e23-a6d1-0ec0b87b1e15', '$N^{1}$: චතුස්තලීය, කෝණික ; $N^{2}$: තලීය ත්‍රිකෝණාකාර, තලීය ත්‍රිකෝණාකාර', '$N^{1}$: චතුස්තලීය, කෝණික ; $N^{2}$: තලීය ත්‍රිකෝණාකාර, තලීය ත්‍රිකෝණාකාර', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('51a55f50-7547-503d-b6c9-fe867aaee756', '3f8797c3-499b-57d1-8b46-d764936b1b22', 7, '<p>පහත දැක්වෙන ප්‍රකාශ අතුරෙන් බෙන්සීන් පිළිබඳව වැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>පහත දැක්වෙන ප්‍රකාශ අතුරෙන් බෙන්සීන් පිළිබඳව වැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'බෙන්සීන්හි සම්ප්‍රයුක්ත මුහුම (resonance hybrid) නිරූපණය කරන්නේ ෂඩස්‍රයක් තුළ කඩඉරි සහිත වළල්ලක් හෝ සම්පූර්ණ කවාකාර වළල්ලක් ඇඳීමෙනි. කීකියුලේ ව්‍යුහ දෙකක් ද්විත්ව හිසැති ඊතලයකින් දැක්වීම සම්ප්‍රයුක්ත මුහුමක් නොව සම්ප්‍රයුක්ත ව්‍යුහ (resonance structures) පවතින බව දැක්වීමට භාවිතා කරන සම්මත ක්‍රමයයි.[cite: 1]', 'බෙන්සීන්හි සම්ප්‍රයුක්ත මුහුම (resonance hybrid) නිරූපණය කරන්නේ ෂඩස්‍රයක් තුළ කඩඉරි සහිත වළල්ලක් හෝ සම්පූර්ණ කවාකාර වළල්ලක් ඇඳීමෙනි. කීකියුලේ ව්‍යුහ දෙකක් ද්විත්ව හිසැති ඊතලයකින් දැක්වීම සම්ප්‍රයුක්ත මුහුමක් නොව සම්ප්‍රයුක්ත ව්‍යුහ (resonance structures) පවතින බව දැක්වීමට භාවිතා කරන සම්මත ක්‍රමයයි.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
