INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5b45be88-c2f9-4309-8ecd-b75ea34151af', '51a55f50-7547-503d-b6c9-fe867aaee756', 'බෙන්සීන්හි කාබන් පරමාණු හයම $sp^{2}$ මුහුම් කරණය වී ඇත.', 'බෙන්සීන්හි කාබන් පරමාණු හයම $sp^{2}$ මුහුම් කරණය වී ඇත.', NULL, 'sanitized', 'v1', 1, 0);
