INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('27c7bedb-ad45-4e99-8a90-809f4e63fffd', '51a55f50-7547-503d-b6c9-fe867aaee756', 'බෙන්සීන්හි සියළු C-C-C හා C-C-H බන්ධන කෝණ වලට එකම අගයක් ඇත.', 'බෙන්සීන්හි සියළු C-C-C හා C-C-H බන්ධන කෝණ වලට එකම අගයක් ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('92fa8190-2f79-45e0-9861-b322746fa1f5', '51a55f50-7547-503d-b6c9-fe867aaee756', 'බෙන්සීන්හි හයිඩ්‍රජන් පරමාණු සියල්ල ම එකම තලයක පිහිටයි.', 'බෙන්සීන්හි හයිඩ්‍රජන් පරමාණු සියල්ල ම එකම තලයක පිහිටයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fba9ea34-cb43-5bbe-99ef-5f6f1f4b95af', '3f8797c3-499b-57d1-8b46-d764936b1b22', 8, '<p>ඉහළ උෂ්ණත්වවල දී $TiCl_{4}(g)$ ද්‍රව මැග්නීසියම් ලෝහය $(Mg(l))$ සමග ප්‍රතික්‍රියා කර $Ti(s)$ ලෝහය සහ $MgCl_{2}(l)$ ලබා දෙයි. $TiCl_{4}(g)$ 0.95 kg හා $Mg(l)$ 97.2 g ප්‍රතික්‍රියා කිරීමට සැලසූ විට, සම්පූර්ණයෙන් වැයවන ප්‍රතික්‍රියකය (මෙය සීමාකාරී ප්‍රතික්‍රියක ලෙස සාමාන්‍යයෙන් හැඳින් වේ) සහ $Ti(s)$ ලෝහය සෑදෙන ප්‍රමාණ පිළිවෙළින් වනුයේ,<br>($TiCl_{4}=190~g~mol^{-1}$ ; $Mg=24.3~g~mol^{-1}$ ; $Ti=48~g~mol^{-1}$)</p>', '<p>ඉහළ උෂ්ණත්වවල දී $TiCl_{4}(g)$ ද්‍රව මැග්නීසියම් ලෝහය $(Mg(l))$ සමග ප්‍රතික්‍රියා කර $Ti(s)$ ලෝහය සහ $MgCl_{2}(l)$ ලබා දෙයි. $TiCl_{4}(g)$ 0.95 kg හා $Mg(l)$ 97.2 g ප්‍රතික්‍රියා කිරීමට සැලසූ විට, සම්පූර්ණයෙන් වැයවන ප්‍රතික්‍රියකය (මෙය සීමාකාරී ප්‍රතික්‍රියක ලෙස සාමාන්‍යයෙන් හැඳින් වේ) සහ $Ti(s)$ ලෝහය සෑදෙන ප්‍රමාණ පිළිවෙළින් වනුයේ,<br>($TiCl_{4}=190~g~mol^{-1}$ ; $Mg=24.3~g~mol^{-1}$ ; $Ti=48~g~mol^{-1}$)</p>', NULL, 'තුලිත රසායනික සමීකරණය: $TiCl_{4}(g) + 2Mg(l) \rightarrow Ti(s) + 2MgCl_{2}(l)$<br>සපයා ඇති $Mg$ මවුල ගණන $= \frac{97.2~g}{24.3~g~mol^{-1}} = 4~mol$<br>සපයා ඇති $TiCl_{4}$ මවුල ගණන $= \frac{0.95 \times 1000~g}{190~g~mol^{-1}} = 5~mol$<br>ස්ටොයිකියෝමිතික අනුපාතයට අනුව 1 mol $TiCl_{4}$ සම්පූර්ණයෙන් ප්‍රතික්‍රියා කිරීමට 2 mol $Mg$ අවශ්‍ය වේ. එබැවින් 4 mol $Mg$ සඳහා වැයවන්නේ $TiCl_{4}$ මවුල 2 ක් පමණි. සම්පූර්ණයෙන්ම වැයවන්නේ (සීමාකාරී ප්‍රතික්‍රියකය) $Mg$ වේ.<br>නිපදවෙන $Ti$ මවුල ගණන $= \frac{4}{2} = 2~mol$<br>නිපදවෙන $Ti$ ස්කන්ධය $= 2~mol \times 48~g~mol^{-1} = 96~g$.[cite: 1]', 'තුලිත රසායනික සමීකරණය: $TiCl_{4}(g) + 2Mg(l) \rightarrow Ti(s) + 2MgCl_{2}(l)$<br>සපයා ඇති $Mg$ මවුල ගණන $= \frac{97.2~g}{24.3~g~mol^{-1}} = 4~mol$<br>සපයා ඇති $TiCl_{4}$ මවුල ගණන $= \frac{0.95 \times 1000~g}{190~g~mol^{-1}} = 5~mol$<br>ස්ටොයිකියෝමිතික අනුපාතයට අනුව 1 mol $TiCl_{4}$ සම්පූර්ණයෙන් ප්‍රතික්‍රියා කිරීමට 2 mol $Mg$ අවශ්‍ය වේ. එබැවින් 4 mol $Mg$ සඳහා වැයවන්නේ $TiCl_{4}$ මවුල 2 ක් පමණි. සම්පූර්ණයෙන්ම වැයවන්නේ (සීමාකාරී ප්‍රතික්‍රියකය) $Mg$ වේ.<br>නිපදවෙන $Ti$ මවුල ගණන $= \frac{4}{2} = 2~mol$<br>නිපදවෙන $Ti$ ස්කන්ධය $= 2~mol \times 48~g~mol^{-1} = 96~g$.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
