INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('70e2f965-1e90-5e6c-aef2-021347c0a254', '3f8797c3-499b-57d1-8b46-d764936b1b22', 14, '<p>පහත දැක්වෙන ඒවායින් නිවැරදි ප්‍රකාශය හඳුනාගන්න.</p>', '<p>පහත දැක්වෙන ඒවායින් නිවැරදි ප්‍රකාශය හඳුනාගන්න.</p>', NULL, '17 වන කාණ්ඩයේ (හැලජන) F හැර අනෙකුත් ප්‍රධාන මූලද්‍රව්‍ය (Cl, Br, I) -1 සිට +7 දක්වා පුළුල් පරාසයක ඔක්සිකරණ අවස්ථා පෙන්වයි. මෙය නිවැරදි ප්‍රකාශයකි. (සැ.යු: වායුමය අවස්ථාවේදී $AlCl_{3}$ ද්විඅවයවිකයක් එනම් $Al_{2}Cl_{6}$ ලෙස පවතින නිසා ඇලුමිනියම් වටා අෂ්ටකය සම්පූර්ණ වන බැවින් 5 වන පිළිතුර ද නිවැරදි ලෙස සැලකිය හැකි බව විභාග දෙපාර්තමේන්තුව සලකා ඇත).[cite: 1]', '17 වන කාණ්ඩයේ (හැලජන) F හැර අනෙකුත් ප්‍රධාන මූලද්‍රව්‍ය (Cl, Br, I) -1 සිට +7 දක්වා පුළුල් පරාසයක ඔක්සිකරණ අවස්ථා පෙන්වයි. මෙය නිවැරදි ප්‍රකාශයකි. (සැ.යු: වායුමය අවස්ථාවේදී $AlCl_{3}$ ද්විඅවයවිකයක් එනම් $Al_{2}Cl_{6}$ ලෙස පවතින නිසා ඇලුමිනියම් වටා අෂ්ටකය සම්පූර්ණ වන බැවින් 5 වන පිළිතුර ද නිවැරදි ලෙස සැලකිය හැකි බව විභාග දෙපාර්තමේන්තුව සලකා ඇත).[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2fd47ed9-e7a6-4c00-84f0-753b5f175ff9', '70e2f965-1e90-5e6c-aef2-021347c0a254', '$NF_{3}$ වල බන්ධන කෝණය $NH_{3}$ වල බන්ධන කෝණයට වඩා විශාල වේ.', '$NF_{3}$ වල බන්ධන කෝණය $NH_{3}$ වල බන්ධන කෝණයට වඩා විශාල වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f5bfbb78-4a9e-48bb-83a5-1313a8df14bc', '70e2f965-1e90-5e6c-aef2-021347c0a254', '17 වන කාණ්ඩයේ (හෝ 7A) මූල ද්‍රව්‍ය, ඔක්සිකරණ අවස්ථා -1 සිට +7 දක්වා පෙන්නුම් කරයි.', '17 වන කාණ්ඩයේ (හෝ 7A) මූල ද්‍රව්‍ය, ඔක්සිකරණ අවස්ථා -1 සිට +7 දක්වා පෙන්නුම් කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e040cec-df70-45fe-bf4e-3c827e524c65', '70e2f965-1e90-5e6c-aef2-021347c0a254', 'කාමර උෂ්ණත්වයේ දී සල්ෆර්වල වඩාත් ම ස්ථායි බහුරූපී ආකාරය ඒකානති සල්ෆර් වේ.', 'කාමර උෂ්ණත්වයේ දී සල්ෆර්වල වඩාත් ම ස්ථායි බහුරූපී ආකාරය ඒකානති සල්ෆර් වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c7d35446-3b66-49fb-8fe3-1f17d7da996d', '70e2f965-1e90-5e6c-aef2-021347c0a254', 'මිනිරන්වල ඝනත්වය දියමන්තිවල ඝනත්වයට වඩා වැඩි ය.', 'මිනිරන්වල ඝනත්වය දියමන්තිවල ඝනත්වයට වඩා වැඩි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('69ece49b-9ef5-48aa-b490-e1f08f229aa8', '70e2f965-1e90-5e6c-aef2-021347c0a254', 'වායුමය අවස්ථාවේ දී ඇලුමිනියම් ක්ලෝරයිඩ් අෂ්ටක නියමය තෘප්ත කරයි.', 'වායුමය අවස්ථාවේ දී ඇලුමිනියම් ක්ලෝරයිඩ් අෂ්ටක නියමය තෘප්ත කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('af85453b-d390-5048-9e04-d46d9cb90425', '3f8797c3-499b-57d1-8b46-d764936b1b22', 15, '<p>$Mn(s) | Mn^{2+}(aq) || Br^{-}(aq) | Br_{2}(g) | Pt(s)$ කෝෂයේ සම්මත විද්‍යුත්ගාමක බලය $2.27~V$ වේ. $Br_{2}(g) | Br^{-}(aq)$ හි සම්මත ඔක්සිහරණ විභවය $1.09~V$ වේ. $Mn^{2+}(aq) | Mn(s)$ හි සම්මත ඔක්සිහරණ විභවය වනුයේ,</p>', '<p>$Mn(s) | Mn^{2+}(aq) || Br^{-}(aq) | Br_{2}(g) | Pt(s)$ කෝෂයේ සම්මත විද්‍යුත්ගාමක බලය $2.27~V$ වේ. $Br_{2}(g) | Br^{-}(aq)$ හි සම්මත ඔක්සිහරණ විභවය $1.09~V$ වේ. $Mn^{2+}(aq) | Mn(s)$ හි සම්මත ඔක්සිහරණ විභවය වනුයේ,</p>', NULL, 'කෝෂ සංකේතනයට අනුව, වම්පස ඇත්තේ ඇනෝඩය ($Mn/Mn^{2+}$) වන අතර දකුණුපස ඇත්තේ කැතෝඩය ($Br_{2}/Br^{-}$) වේ.<br>කෝෂයේ සම්මත විද්‍යුත්ගාමක බලය සෙවීමේ සූත්‍රය:<br>$E_{cell}^{\ominus} = E_{cathode}^{\ominus} - E_{anode}^{\ominus}$<br>$2.27~V = 1.09~V - E_{Mn^{2+}/Mn}^{\ominus}$<br>$E_{Mn^{2+}/Mn}^{\ominus} = 1.09~V - 2.27~V = -1.18~V$.[cite: 1]', 'කෝෂ සංකේතනයට අනුව, වම්පස ඇත්තේ ඇනෝඩය ($Mn/Mn^{2+}$) වන අතර දකුණුපස ඇත්තේ කැතෝඩය ($Br_{2}/Br^{-}$) වේ.<br>කෝෂයේ සම්මත විද්‍යුත්ගාමක බලය සෙවීමේ සූත්‍රය:<br>$E_{cell}^{\ominus} = E_{cathode}^{\ominus} - E_{anode}^{\ominus}$<br>$2.27~V = 1.09~V - E_{Mn^{2+}/Mn}^{\ominus}$<br>$E_{Mn^{2+}/Mn}^{\ominus} = 1.09~V - 2.27~V = -1.18~V$.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
