INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dcb24ea7-a0b4-5959-ad2f-1f9d77f285fd', '3f8797c3-499b-57d1-8b46-d764936b1b22', 17, '<p>$C_{6}H_{5}\overset{+}{N}\equiv NCl^{-}$ පිළිබඳව වැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>$C_{6}H_{5}\overset{+}{N}\equiv NCl^{-}$ පිළිබඳව වැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'බෙන්සීන් ඩයසෝනියම් ක්ලෝරයිඩ් ජලීය ද්‍රාවණයක් සමග රත් කළ විට ජල විච්ඡේදනය වී ෆීනෝල් ($C_{6}H_{5}OH$) සහ නයිට්‍රජන් වායුව ($N_{2}$) ලබා දෙයි; බෙන්සීන් නොලැබේ.[cite: 1]', 'බෙන්සීන් ඩයසෝනියම් ක්ලෝරයිඩ් ජලීය ද්‍රාවණයක් සමග රත් කළ විට ජල විච්ඡේදනය වී ෆීනෝල් ($C_{6}H_{5}OH$) සහ නයිට්‍රජන් වායුව ($N_{2}$) ලබා දෙයි; බෙන්සීන් නොලැබේ.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4ff765d6-bab9-4c84-a5ed-1f754dddc8b8', 'dcb24ea7-a0b4-5959-ad2f-1f9d77f285fd', 'ඇනිලීන්, $HNO_{2}(NaNO_{2}/HCl)$ සමග $0-5^{\circ}C$ දී ප්‍රතික්‍රියා කරවීමෙන් $C_{6}H_{5}N\equiv NCl^{-}$ ලබා ගත හැක.', 'ඇනිලීන්, $HNO_{2}(NaNO_{2}/HCl)$ සමග $0-5^{\circ}C$ දී ප්‍රතික්‍රියා කරවීමෙන් $C_{6}H_{5}N\equiv NCl^{-}$ ලබා ගත හැක.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0e4f5d80-bae4-4d09-93ac-3009febc0ce0', 'dcb24ea7-a0b4-5959-ad2f-1f9d77f285fd', '$C_{6}H_{5}N\equiv NCl^{-}$, $KI$ සමග ප්‍රතික්‍රියා කර අයඩොබෙන්සීන් ලබා දෙයි.', '$C_{6}H_{5}N\equiv NCl^{-}$, $KI$ සමග ප්‍රතික්‍රියා කර අයඩොබෙන්සීන් ලබා දෙයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c9924fe8-d6ad-43aa-8095-44f2d6b3816c', 'dcb24ea7-a0b4-5959-ad2f-1f9d77f285fd', '$C_{6}H_{5}\overset{+}{N}\equiv N$ අයනයට ඉලෙක්ට්‍රෝෆයිලයක් ලෙස ක්‍රියා කළ හැකි ය.', '$C_{6}H_{5}\overset{+}{N}\equiv N$ අයනයට ඉලෙක්ට්‍රෝෆයිලයක් ලෙස ක්‍රියා කළ හැකි ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('177eb82b-091e-4788-bb98-b27c89f99194', 'dcb24ea7-a0b4-5959-ad2f-1f9d77f285fd', '$C_{6}H_{5}N\equiv NCl^{-}$ හි ජලීය ද්‍රාවණයක් රත් කළ විට එය වියෝජනය වී බෙන්සීන් ලබා දෙයි.', '$C_{6}H_{5}N\equiv NCl^{-}$ හි ජලීය ද්‍රාවණයක් රත් කළ විට එය වියෝජනය වී බෙන්සීන් ලබා දෙයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dee38143-e470-48af-8ac5-8986a5f005d8', 'dcb24ea7-a0b4-5959-ad2f-1f9d77f285fd', '$C_{6}H_{5}\overset{+}{N}\equiv NCl^{-}$ භාෂ්මික මාධ්‍යයේ දී ෆීනෝල් සමග ප්‍රතික්‍රියා කර වර්ණවත් සංයෝග සාදයි.', '$C_{6}H_{5}\overset{+}{N}\equiv NCl^{-}$ භාෂ්මික මාධ්‍යයේ දී ෆීනෝල් සමග ප්‍රතික්‍රියා කර වර්ණවත් සංයෝග සාදයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3536700f-40b7-5ef9-bb28-d1044f5cda91', '3f8797c3-499b-57d1-8b46-d764936b1b22', 18, '<p>$H_{2}S(g)$, $O_{2}(g)$ සමග ප්‍රතික්‍රියා කර ඵල ලෙස ජලවාෂ්ප ($H_{2}O(g)$) සහ $SO_{2}(g)$ පමණක් ලබා දේ. නියත පීඩනයක දී සහ $250^{\circ}C$ හි දී $H_{2}S(g)$ $4~dm^{3}$ ක් හා $O_{2}(g)$ $10~dm^{3}$ ක් ප්‍රතික්‍රියා කළ විට මිශ්‍රණයේ අවසාන පරිමාව වනුයේ,</p>', '<p>$H_{2}S(g)$, $O_{2}(g)$ සමග ප්‍රතික්‍රියා කර ඵල ලෙස ජලවාෂ්ප ($H_{2}O(g)$) සහ $SO_{2}(g)$ පමණක් ලබා දේ. නියත පීඩනයක දී සහ $250^{\circ}C$ හි දී $H_{2}S(g)$ $4~dm^{3}$ ක් හා $O_{2}(g)$ $10~dm^{3}$ ක් ප්‍රතික්‍රියා කළ විට මිශ්‍රණයේ අවසාන පරිමාව වනුයේ,</p>', NULL, 'තුලිත සමීකරණය: $2H_{2}S(g) + 3O_{2}(g) \rightarrow 2H_{2}O(g) + 2SO_{2}(g)$<br>ප්‍රතික්‍රියා කරන අනුපාතය $2:3$ වේ. $H_{2}S$ පරිමාව $4~dm^{3}$ ක් ප්‍රතික්‍රියා කිරීමට $O_{2}$ පරිමාව $6~dm^{3}$ ක් අවශ්‍ය වේ. එබැවින් $H_{2}S$ සීමාකාරී වේ.<br>ඉතිරි වන $O_{2}$ පරිමාව $= 10 - 6 = 4~dm^{3}$<br>සෑදෙන $H_{2}O(g)$ පරිමාව $= 4~dm^{3}$<br>සෑදෙන $SO_{2}(g)$ පරිමාව $= 4~dm^{3}$<br>අවසාන මුළු පරිමාව $= 4 + 4 + 4 = 12~dm^{3}$.[cite: 1]', 'තුලිත සමීකරණය: $2H_{2}S(g) + 3O_{2}(g) \rightarrow 2H_{2}O(g) + 2SO_{2}(g)$<br>ප්‍රතික්‍රියා කරන අනුපාතය $2:3$ වේ. $H_{2}S$ පරිමාව $4~dm^{3}$ ක් ප්‍රතික්‍රියා කිරීමට $O_{2}$ පරිමාව $6~dm^{3}$ ක් අවශ්‍ය වේ. එබැවින් $H_{2}S$ සීමාකාරී වේ.<br>ඉතිරි වන $O_{2}$ පරිමාව $= 10 - 6 = 4~dm^{3}$<br>සෑදෙන $H_{2}O(g)$ පරිමාව $= 4~dm^{3}$<br>සෑදෙන $SO_{2}(g)$ පරිමාව $= 4~dm^{3}$<br>අවසාන මුළු පරිමාව $= 4 + 4 + 4 = 12~dm^{3}$.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
