INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('83010f43-5fc8-44b9-901d-5926252b8b8a', '2d61be36-140c-52fe-ba0f-d68ba12ba76e', 'අඩු වේ, වැඩි වේ, වෙනස් නොවේ.', 'අඩු වේ, වැඩි වේ, වෙනස් නොවේ.', NULL, 'sanitized', 'v1', 0, 1);
