INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ca19c047-bfe9-4608-a738-c28c77c1db06', '2d61be36-140c-52fe-ba0f-d68ba12ba76e', 'වැඩි වේ, වෙනස් නොවේ, වෙනස් නොවේ.', 'වැඩි වේ, වෙනස් නොවේ, වෙනස් නොවේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7feb3452-3d6a-4aeb-b999-7b32df890a81', '2d61be36-140c-52fe-ba0f-d68ba12ba76e', 'වැඩි වේ, වෙනස් නොවේ, වැඩි වේ.', 'වැඩි වේ, වෙනස් නොවේ, වැඩි වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a595fe3-fb8e-4481-a7ac-dae322de7043', '2d61be36-140c-52fe-ba0f-d68ba12ba76e', 'වැඩි වේ, වැඩි වේ, වැඩි වේ.', 'වැඩි වේ, වැඩි වේ, වැඩි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6c5cf64d-62c6-537b-ad1a-5028b3485dc9', '3f8797c3-499b-57d1-8b46-d764936b1b22', 23, '<p>ක්ලෝරින්හි ඔක්සො අම්ල වන $HOCl$, $HClO_{2}$, $HClO_{3}$ හා $HClO_{4}$ පිළිබඳ වැරදි වගන්තිය වනුයේ,</p>', '<p>ක්ලෝරින්හි ඔක්සො අම්ල වන $HOCl$, $HClO_{2}$, $HClO_{3}$ හා $HClO_{4}$ පිළිබඳ වැරදි වගන්තිය වනුයේ,</p>', NULL, '$HOCl$ හි ව්‍යුහය $H-O-Cl$ වන අතර එහි කිසිදු ද්විත්ව බන්ධනයක් නොමැත. එබැවින් ''සියල්ලෙහි ම අඩු තරමින් එක් ද්විත්ව බන්ධනයක්වත් අඩංගු වේ'' යන ප්‍රකාශය වැරදිය.[cite: 1]', '$HOCl$ හි ව්‍යුහය $H-O-Cl$ වන අතර එහි කිසිදු ද්විත්ව බන්ධනයක් නොමැත. එබැවින් ''සියල්ලෙහි ම අඩු තරමින් එක් ද්විත්ව බන්ධනයක්වත් අඩංගු වේ'' යන ප්‍රකාශය වැරදිය.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b4203f0b-e922-4b62-8ec0-ce044db050d1', '6c5cf64d-62c6-537b-ad1a-5028b3485dc9', '$HClO_{2}$, $HClO_{3}$ හා $HClO_{4}$ හි ක්ලෝරීන් වටා හැඩයන් පිළිවෙළින් කෝණික, පිරමිඩීය හා චතුස්තලීය වේ.', '$HClO_{2}$, $HClO_{3}$ හා $HClO_{4}$ හි ක්ලෝරීන් වටා හැඩයන් පිළිවෙළින් කෝණික, පිරමිඩීය හා චතුස්තලීය වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('43a64d98-e131-437f-846d-324270519f5c', '6c5cf64d-62c6-537b-ad1a-5028b3485dc9', '$HOCl$, $HClO_{2}$, $HClO_{3}$ හා $HClO_{4}$ හි ක්ලෝරීන් වල ඔක්සිකරණ අවස්ථා පිළිවෙළින් +1, +3, +5 හා +7 වේ.', '$HOCl$, $HClO_{2}$, $HClO_{3}$ හා $HClO_{4}$ හි ක්ලෝරීන් වල ඔක්සිකරණ අවස්ථා පිළිවෙළින් +1, +3, +5 හා +7 වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d837d102-a878-49bf-aa5f-8ac7e528e92f', '6c5cf64d-62c6-537b-ad1a-5028b3485dc9', 'ඔක්සොඅම්ලවල අම්ල ප්‍රබලතාව $HOCl < HClO_{2} < HClO_{3} < HClO_{4}$ ලෙස වෙනස් වේ.', 'ඔක්සොඅම්ලවල අම්ල ප්‍රබලතාව $HOCl < HClO_{2} < HClO_{3} < HClO_{4}$ ලෙස වෙනස් වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a4afd598-0f0b-4ceb-b7c3-e80c86774a23', '6c5cf64d-62c6-537b-ad1a-5028b3485dc9', 'මෙම ඔක්සොඅම්ල සියල්ලෙහි ම අඩු තරමින් එක් ද්විත්ව බන්ධනයක්වත් අඩංගු වේ.', 'මෙම ඔක්සොඅම්ල සියල්ලෙහි ම අඩු තරමින් එක් ද්විත්ව බන්ධනයක්වත් අඩංගු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('528f4d7d-f34a-425b-8cc9-07215495bae4', '6c5cf64d-62c6-537b-ad1a-5028b3485dc9', 'මෙම ඔක්සොඅම්ල සියල්ලෙහි ම අඩු තරමින් එක් OH කාණ්ඩයක්වත් අඩංගු වේ.', 'මෙම ඔක්සොඅම්ල සියල්ලෙහි ම අඩු තරමින් එක් OH කාණ්ඩයක්වත් අඩංගු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cadd6825-f39c-516c-94e7-1d846795e87e', '3f8797c3-499b-57d1-8b46-d764936b1b22', 24, '<p>ආම්ලික ජලීය ද්‍රාවණයක $25^{\circ}C$ හි දී ඝනත්වය $1.0~kg~dm^{-3}$ වේ. මෙම ද්‍රාවණයෙහි $pH$ අගය 1.0 වේ නම් එහි $H^{+}$ සාන්ද්‍රණය ppm වලින් වනුයේ,</p>', '<p>ආම්ලික ජලීය ද්‍රාවණයක $25^{\circ}C$ හි දී ඝනත්වය $1.0~kg~dm^{-3}$ වේ. මෙම ද්‍රාවණයෙහි $pH$ අගය 1.0 වේ නම් එහි $H^{+}$ සාන්ද්‍රණය ppm වලින් වනුයේ,</p>', NULL, '$pH = 1.0$ බැවින් $[H^{+}] = 10^{-1}~mol~dm^{-3} = 0.1~mol~dm^{-3}$.<br>$H^{+}$ හි මවුලික ස්කන්ධය $\approx 1.0~g~mol^{-1}$ බැවින් ද්‍රාවණයේ $dm^{3}$ ක අඩංගු $H^{+}$ ස්කන්ධය $= 0.1~g$.<br>ද්‍රාවණයේ ඝනත්වය $= 1.0~kg~dm^{-3} = 1000~g~dm^{-3}$.<br>$ppm = \frac{\text{ද්‍රාව්‍ය ස්කන්ධය}}{\text{ද්‍රාවණයේ ස්කන්ධය}} \times 10^{6} = \frac{0.1~g}{1000~g} \times 10^{6} = 100~ppm$.[cite: 1]', '$pH = 1.0$ බැවින් $[H^{+}] = 10^{-1}~mol~dm^{-3} = 0.1~mol~dm^{-3}$.<br>$H^{+}$ හි මවුලික ස්කන්ධය $\approx 1.0~g~mol^{-1}$ බැවින් ද්‍රාවණයේ $dm^{3}$ ක අඩංගු $H^{+}$ ස්කන්ධය $= 0.1~g$.<br>ද්‍රාවණයේ ඝනත්වය $= 1.0~kg~dm^{-3} = 1000~g~dm^{-3}$.<br>$ppm = \frac{\text{ද්‍රාව්‍ය ස්කන්ධය}}{\text{ද්‍රාවණයේ ස්කන්ධය}} \times 10^{6} = \frac{0.1~g}{1000~g} \times 10^{6} = 100~ppm$.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
