INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f381c936-042e-5a36-8907-32ec00d881f5', '3f8797c3-499b-57d1-8b46-d764936b1b22', 26, '<p>$NaCl(s)$ උත්පාදනයට අදාළ බෝන් - හේබර් චක්‍රයෙහි අඩංගු නොවන්නේ පහත සඳහන් කුමන ප්‍රතික්‍රියා පියවර ද?</p>', '<p>$NaCl(s)$ උත්පාදනයට අදාළ බෝන් - හේබර් චක්‍රයෙහි අඩංගු නොවන්නේ පහත සඳහන් කුමන ප්‍රතික්‍රියා පියවර ද?</p>', NULL, 'බෝන්-හේබර් චක්‍රය යොදා ගැනෙන්නේ ඝන අයනික සංයෝගයක් එහි මූලද්‍රව්‍යවලින් සෑදීමේදී සිදුවන ශක්ති විපර්යාසයන් සම්බන්ධ කිරීම සඳහාය. එහිදී ජලීය ද්‍රාවණ කලාපයට අදාළ පියවර (අයන ජලනය වීම) අඩංගු නොවේ.[cite: 1]', 'බෝන්-හේබර් චක්‍රය යොදා ගැනෙන්නේ ඝන අයනික සංයෝගයක් එහි මූලද්‍රව්‍යවලින් සෑදීමේදී සිදුවන ශක්ති විපර්යාසයන් සම්බන්ධ කිරීම සඳහාය. එහිදී ජලීය ද්‍රාවණ කලාපයට අදාළ පියවර (අයන ජලනය වීම) අඩංගු නොවේ.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a72477eb-0c61-4bd9-816a-d4eebd865b6d', 'f381c936-042e-5a36-8907-32ec00d881f5', '$Na^{+}(aq) + Cl^{-}(aq) \rightarrow NaCl(aq)$', '$Na^{+}(aq) + Cl^{-}(aq) \rightarrow NaCl(aq)$', NULL, 'sanitized', 'v1', 0, 1);
