INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('26951247-3136-5c43-9651-051cbb3ad23c', '3f8797c3-499b-57d1-8b46-d764936b1b22', 27, '<p>$A(g) + B(g) \\rightarrow C(g)$ යන මූලික ප්‍රතික්‍රියාවෙහි සක්‍රියන ශක්තිය $E_{a}$ වේ. $M$ ලෝහය මගින් මෙම ප්‍රතික්‍රියාව උත්ප්‍රේරණය වේ. උත්ප්‍රේරිත ප්‍රතික්‍රියාවෙහි ශක්ති සටහන පහත දැක්වේ.<br><br>මෙම ප්‍රතික්‍රියාව සම්බන්ධයෙන් පහත දී ඇති කුමක් හැමවිට ම සත්‍ය වේ ද?</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e3468b7b-c803-4b86-831c-7213354e86f6', '26951247-3136-5c43-9651-051cbb3ad23c', '$E_{a} < E_{1}$', '$E_{a} < E_{1}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a498aa5a-1c4b-47ce-92c4-aa325ef256fc', '26951247-3136-5c43-9651-051cbb3ad23c', '$E_{a} = E_{1} + E_{2} + E_{3} - \Delta H_{1}$', '$E_{a} = E_{1} + E_{2} + E_{3} - \Delta H_{1}$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aac3f2bf-a00d-4a0e-b34c-50d3f42733f9', '26951247-3136-5c43-9651-051cbb3ad23c', '$E_{a} < E_{1}$, $E_{a} < E_{2}$ සහ $E_{a} < E_{3}$', '$E_{a} < E_{1}$, $E_{a} < E_{2}$ සහ $E_{a} < E_{3}$', NULL, 'sanitized', 'v1', 2, 0);
