INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9416ea90-4866-4923-a89e-fd91770caaf0', '30fb7df6-520b-5b57-adb4-2593489127d2', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8ce35c69-d312-57ca-a838-240121cdfcd7', '3f8797c3-499b-57d1-8b46-d764936b1b22', 46, '<p>$CH_{3}-CH=CH_{2} \xrightarrow{HBr} CH_{3}-CH(Br)-CH_{3}$ ප්‍රතික්‍රියාව, නියුක්ලියෝෆිලික ආකලන ප්‍රතික්‍රියාවකි.<br><br>ද්විතීයික කාබොකැටායනයක් ප්‍රතික්‍රියා අතරමැදියක් ලෙස පහත දැක්වෙන ප්‍රතික්‍රියාවේදී සෑදේ.<br>$CH_{3}-CH=CH_{2} \xrightarrow{HBr} CH_{3}-CH(Br)-CH_{3}$</p>', '<p>$CH_{3}-CH=CH_{2} \xrightarrow{HBr} CH_{3}-CH(Br)-CH_{3}$ ප්‍රතික්‍රියාව, නියුක්ලියෝෆිලික ආකලන ප්‍රතික්‍රියාවකි.<br><br>ද්විතීයික කාබොකැටායනයක් ප්‍රතික්‍රියා අතරමැදියක් ලෙස පහත දැක්වෙන ප්‍රතික්‍රියාවේදී සෑදේ.<br>$CH_{3}-CH=CH_{2} \xrightarrow{HBr} CH_{3}-CH(Br)-CH_{3}$</p>', NULL, 'පළමු ප්‍රකාශය අසත්‍ය වේ; ඇල්කීන (ප්‍රොපීන්) සහ $HBr$ අතර සිදුවන්නේ ඉලෙක්ට්‍රෝෆිලික ආකලන (Electrophilic addition) ප්‍රතික්‍රියාවකි. දෙවන ප්‍රකාශය සත්‍ය වේ; මෙහිදී මාකෝනිකොෆ් නියමයට අනුව වඩාත් ස්ථායි ද්විතීයික කාබොකැටායනයක් ($CH_{3}-\overset{+}{C}H-CH_{3}$) අතරමැදියක් ලෙස සෑදේ.[cite: 1]', 'පළමු ප්‍රකාශය අසත්‍ය වේ; ඇල්කීන (ප්‍රොපීන්) සහ $HBr$ අතර සිදුවන්නේ ඉලෙක්ට්‍රෝෆිලික ආකලන (Electrophilic addition) ප්‍රතික්‍රියාවකි. දෙවන ප්‍රකාශය සත්‍ය වේ; මෙහිදී මාකෝනිකොෆ් නියමයට අනුව වඩාත් ස්ථායි ද්විතීයික කාබොකැටායනයක් ($CH_{3}-\overset{+}{C}H-CH_{3}$) අතරමැදියක් ලෙස සෑදේ.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f09d1a94-6d41-4c7e-b967-7550bb1ecf8d', '8ce35c69-d312-57ca-a838-240121cdfcd7', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', NULL, 'sanitized', 'v1', 0, 1);
