INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d5e9610a-42b6-4bcf-9367-6bcaf7beac2c', '8ce35c69-d312-57ca-a838-240121cdfcd7', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('58fd90f6-c643-57ac-87ef-96a614261c7d', '3f8797c3-499b-57d1-8b46-d764936b1b22', 47, '<p>කාර්මික ක්‍රියාවලි කිහිපයකම කෝක් (Coke) භාවිත වේ.<br><br>කාර්මිකව කෝක් (Coke) භාවිත වන්නේ ඉන්ධනයක් ලෙස පමණි.</p>', '<p>කාර්මික ක්‍රියාවලි කිහිපයකම කෝක් (Coke) භාවිත වේ.<br><br>කාර්මිකව කෝක් (Coke) භාවිත වන්නේ ඉන්ධනයක් ලෙස පමණි.</p>', NULL, 'පළමු ප්‍රකාශය සත්‍ය වේ; කෝක් යකඩ නිස්සාරණය වැනි කාර්මික ක්‍රියාවලි වල බහුලව යොදා ගැනේ. දෙවන ප්‍රකාශය අසත්‍ය වේ; කෝක් යනු ඉන්ධනයක් මෙන්ම ප්‍රබල ඔක්සිහාරකයක් ද වේ (උදා: යකඩ නිස්සාරණයේදී යකඩ ඔක්සයිඩ, ලෝහික යකඩ බවට ඔක්සිහරණය කිරීම සඳහා කෝක් යොදා ගනී).[cite: 1]', 'පළමු ප්‍රකාශය සත්‍ය වේ; කෝක් යකඩ නිස්සාරණය වැනි කාර්මික ක්‍රියාවලි වල බහුලව යොදා ගැනේ. දෙවන ප්‍රකාශය අසත්‍ය වේ; කෝක් යනු ඉන්ධනයක් මෙන්ම ප්‍රබල ඔක්සිහාරකයක් ද වේ (උදා: යකඩ නිස්සාරණයේදී යකඩ ඔක්සයිඩ, ලෝහික යකඩ බවට ඔක්සිහරණය කිරීම සඳහා කෝක් යොදා ගනී).[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f772267-4a4f-4ca8-86ac-90e26f84da6e', '58fd90f6-c643-57ac-87ef-96a614261c7d', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bae39d8f-800a-44c6-9fbc-efbb50b56b39', '58fd90f6-c643-57ac-87ef-96a614261c7d', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා නොදෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන නමුත් පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා නොදෙයි.', NULL, 'sanitized', 'v1', 1, 0);
