INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e99523fb-0103-4126-94a7-ea61929b823e', '58fd90f6-c643-57ac-87ef-96a614261c7d', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමු වැනි ප්‍රකාශය අසත්‍ය වේ. දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bdd4bd9d-9b95-5419-aca1-69bf651fbffc', '3f8797c3-499b-57d1-8b46-d764936b1b22', 48, '<p>කීටෝනයක කාබනයිල් කාබන් පරමාණුව සහ එයට බන්ධනය වූ අනෙකුත් පරමාණු එකම තලයක පිහිටයි.<br><br>කීටෝනයක කාබනයිල් කාබන් පරමාණුව $sp^{2}$ මුහුම් කරණය වී ඇත.</p>', '<p>කීටෝනයක කාබනයිල් කාබන් පරමාණුව සහ එයට බන්ධනය වූ අනෙකුත් පරමාණු එකම තලයක පිහිටයි.<br><br>කීටෝනයක කාබනයිල් කාබන් පරමාණුව $sp^{2}$ මුහුම් කරණය වී ඇත.</p>', NULL, 'පළමු ප්‍රකාශය සත්‍ය වේ; කීටෝනයක කාබනයිල් කාණ්ඩය වටා ජ්‍යාමිතිය තලීය ත්‍රිකෝණාකාර වේ. දෙවන ප්‍රකාශය ද සත්‍ය වේ; කාබනයිල් කාබන් පරමාණුව $sp^{2}$ මුහුම්කරණය වී ඇති අතර, එය එසේ තලීය ත්‍රිකෝණාකාර ජ්‍යාමිතියක් ලබා දීමට හේතු වේ. එබැවින් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.[cite: 1]', 'පළමු ප්‍රකාශය සත්‍ය වේ; කීටෝනයක කාබනයිල් කාණ්ඩය වටා ජ්‍යාමිතිය තලීය ත්‍රිකෝණාකාර වේ. දෙවන ප්‍රකාශය ද සත්‍ය වේ; කාබනයිල් කාබන් පරමාණුව $sp^{2}$ මුහුම්කරණය වී ඇති අතර, එය එසේ තලීය ත්‍රිකෝණාකාර ජ්‍යාමිතියක් ලබා දීමට හේතු වේ. එබැවින් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.[cite: 1]', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fa4acd95-551d-4cbb-b9bb-f2e83d9a48d6', 'bdd4bd9d-9b95-5419-aca1-69bf651fbffc', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', 'පළමු වැනි ප්‍රකාශය සත්‍ය වේ. දෙවැනි ප්‍රකාශය සත්‍ය වන අතර, පළමු වැනි ප්‍රකාශය නිවැරදි ව පහදා දෙයි.', NULL, 'sanitized', 'v1', 0, 1);
