INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6b675cd3-df98-5c7a-b485-d1ffcc570361', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 4, '<p>Consider the following statements about a pair of action-reaction forces. <br><br> (A) They are equal in magnitude but opposite in direction. <br> (B) They act only on objects touching each other. <br> (C) They act on the same object. <br><br> Of the above statements</p>', '<p>Consider the following statements about a pair of action-reaction forces. <br><br> (A) They are equal in magnitude but opposite in direction. <br> (B) They act only on objects touching each other. <br> (C) They act on the same object. <br><br> Of the above statements</p>', NULL, 'According to Newton''s Third Law of Motion, action and reaction forces are always equal in magnitude and opposite in direction (Statement A is true). They act on two different objects, never on the same object (Statement C is false). Action-reaction pairs can also occur at a distance without physical contact, such as gravitational or electromagnetic forces (Statement B is false).', 'According to Newton''s Third Law of Motion, action and reaction forces are always equal in magnitude and opposite in direction (Statement A is true). They act on two different objects, never on the same object (Statement C is false). Action-reaction pairs can also occur at a distance without physical contact, such as gravitational or electromagnetic forces (Statement B is false).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
