INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9a21f2de-803e-56ec-a1cd-95aab8f5a76f', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 6, '<p>Consider following statements about a muon ($\mu$). <br><br> (A) It is a lepton. <br> (B) It is made out of three quarks. <br> (C) Its mass is larger than that of an electron. <br><br> Of the above statements</p>', '<p>Consider following statements about a muon ($\mu$). <br><br> (A) It is a lepton. <br> (B) It is made out of three quarks. <br> (C) Its mass is larger than that of an electron. <br><br> Of the above statements</p>', NULL, 'A muon is an elementary particle classified as a lepton, similar to an electron (Statement A is true). Because it is a fundamental elementary particle, it is not composed of quarks; only hadrons like protons and neutrons are made of quarks (Statement B is false). The mass of a muon is approximately 207 times greater than the mass of an electron (Statement C is true).', 'A muon is an elementary particle classified as a lepton, similar to an electron (Statement A is true). Because it is a fundamental elementary particle, it is not composed of quarks; only hadrons like protons and neutrons are made of quarks (Statement B is false). The mass of a muon is approximately 207 times greater than the mass of an electron (Statement C is true).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, 