INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e618f967-a114-54d7-aac4-ff30488303c4', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 9, '<p>An astronomical telescope is in normal adjustment. If the focal length of objective lens is $80\text{ cm}$ and the angular magnification is 20, what is the distance between the objective lens and the eyepiece?</p>', '<p>An astronomical telescope is in normal adjustment. If the focal length of objective lens is $80\text{ cm}$ and the angular magnification is 20, what is the distance between the objective lens and the eyepiece?</p>', NULL, 'For an astronomical telescope in normal adjustment, the angular magnification ($M$) is given by the ratio of the focal length of the objective lens ($f_o$) to the focal length of the eyepiece ($f_e$): <br> $M = \frac{f_o}{f_e}$ <br> Given $M = 20$ and $f_o = 80\text{ cm}$, we can find $f_e$: <br> $20 = \frac{80\text{ cm}}{f_e} \implies f_e = 4\text{ cm}$ <br> The distance between the objective lens and the eyepiece ($L$) in normal adjustment is the sum of their focal lengths: <br> $L = f_o + f_e = 80\text{ cm} + 4\text{ cm} = 84\text{ cm}$', 'For an astronomical telescope in normal adjustment, the angular magnification ($M$) is given by the ratio of the focal length of the objective lens ($f_o$) to the focal length of the eyepiece ($f_e$): <br> $M = \frac{f_o}{f_e}$ <br> Given $M = 20$ and $f_o = 80\text{ cm}$, we can find $f_e$: <br> $20 = \frac{80\text{ cm}}{f_e} \implies f_e = 4\text{ cm}$ <br> The distance between the objective lens and the eyepiece ($L$) in normal adjustment is the sum of their focal lengths: <br> $L = f_o + f_e = 80\text{ cm} + 4\text{ cm} = 84\text{ cm}$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
