INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('43a7a3f9-636c-51a4-b1d1-c9ea5b1d7711', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 11, '<p>Faraday''s law of electromagnetic induction is related to</p>', '<p>Faraday''s law of electromagnetic induction is related to</p>', NULL, 'Faraday''s law of electromagnetic induction states that the induced electromotive force (EMF) is proportional to the rate of change of magnetic flux. This, combined with Lenz''s law, dictates that the direction of the induced current opposes the change in flux. This opposition means mechanical work must be continuously done to keep a conductor moving in a magnetic field, which is then converted into electrical energy. Thus, it fundamentally satisfies the law of conservation of energy.', 'Faraday''s law of electromagnetic induction states that the induced electromotive force (EMF) is proportional to the rate of change of magnetic flux. This, combined with Lenz''s law, dictates that the direction of the induced current opposes the change in flux. This opposition means mechanical work must be continuously done to keep a conductor moving in a magnetic field, which is then converted into electrical energy. Thus, it fundamentally satisfies the law of conservation of energy.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
