INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('451a4c27-46d2-5629-804f-61716d166902', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 12, '<p>From a homogeneous uniform circular plate of radius $2r$ a circular part of radius $r$ is removed as shown in the figure. The centre of gravity of the remaining part of the plate is most likely to be found at</p>', '<p>From a homogeneous uniform circular plate of radius $2r$ a circular part of radius $r$ is removed as shown in the figure. The centre of gravity of the remaining part of the plate is most likely to be found at</p>', NULL, 'Let the center of the original uncut plate be point C at coordinate $(0,0)$. Mass is proportional to area. <br> The area of the large plate is $\pi(2r)^2 = 4\pi r^2$, so let its mass be $4m$ with its center at $x = 0$. <br> The removed circular part has radius $r$ and area $\pi r^2$, so its mass is $m$, with its center located at $x = -r$ (point A). <br> The remaining part has mass $3m$ and its center of mass is at $x$. <br> Using the principle of superposition and equating moments about the origin: <br> $4m(0) = m(-r) + 3m(x)$ <br> $3mx = mr \implies x = +\frac{r}{3}$ <br> Point C is at $0$, and positive $x$ is to the right. Looking at the figure, point D is positioned to the right of the center C, making it the most likely position for the new center of gravity.', 'Let the center of the original uncut plate be point C at coordinate $(0,0)$. Mass is proportional to area. <br> The area of the large plate is $\pi(2r)^2 = 4\pi r^2$, so let its mass be $4m$ with its center at $x = 0$. <br> The removed circular part has radius $r$ and area $\pi r^2$, so its mass is $m$, with its center located at $x = -r$ (point A). <br> The remaining part has mass $3m$ and its center of mass is at $x$. <br> Using the principle of superposition and equating moments about the origin: <br> $4m(0) = m(-r) + 3m(x)$ <br> $3mx = mr \implies x = +\frac{r}{3}$ <br> Point C is at $0$, and positive $x$ is to the right. Looking at the figure, point D is positioned to the right of the center C, making it the most likely position for the new center of gravity.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
