INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1ad6a3b3-60a1-58f3-b529-713cda5fd712', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 22, '<p>In a uniformly charged hollow metallic spherical shell, the variation of the electric potential ($V$) with distance ($r$) from center is best represented by,</p>', '<p>In a uniformly charged hollow metallic spherical shell, the variation of the electric potential ($V$) with distance ($r$) from center is best represented by,</p>', NULL, 'For a uniformly charged hollow metallic spherical shell, the electric field inside the shell is zero. Because the electric field is the negative gradient of the potential ($E = -\frac{dV}{dr}$), a zero electric field implies that the electric potential $V$ is constant everywhere inside the shell and is equal to the potential at its surface ($V = \frac{1}{4\pi\epsilon_0}\frac{Q}{R}$). Outside the shell ($r > R$), it behaves like a point charge located at the center, and the potential is inversely proportional to the distance $r$ ($V \propto \frac{1}{r}$). Graph (2) correctly illustrates a constant horizontal line up to $r = R$, followed by a curve decreasing as $1/r$.', 'For a uniformly charged hollow metallic spherical shell, the electric field inside the shell is zero. Because the electric field is the negative gradient of the potential ($E = -\frac{dV}{dr}$), a zero electric field implies that the electric potential $V$ is constant everywhere inside the shell and is equal to the potential at its surface ($V = \frac{1}{4\pi\epsilon_0}\frac{Q}{R}$). Outside the shell ($r > R$), it behaves like a point charge located at the center, and the potential is inversely proportional to the distance $r$ ($V \propto \frac{1}{r}$). Graph (2) correctly illustrates a constant horizontal line up to $r = R$, followed by a curve decreasing as $1/r$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
