INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('693199f4-e83c-527c-8b34-c47fde9253c4', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 24, '<p>A current $I$ flows through a uniform metal wire which is maintained at a constant temperature. Which of the following graphs best represents the variation of power dissipation $P$ in the wire with current $I$ in the wire?</p>', '<p>A current $I$ flows through a uniform metal wire which is maintained at a constant temperature. Which of the following graphs best represents the variation of power dissipation $P$ in the wire with current $I$ in the wire?</p>', NULL, 'The power dissipated by an electrical resistance is given by the formula $P = I^2 R$. Because the metal wire is maintained at a constant temperature, its resistance $R$ remains constant. Therefore, power $P$ is directly proportional to the square of the current $I$ ($P \propto I^2$). Mathematically, this is a parabola that opens upwards and passes through the origin. Graph (3) correctly depicts this parabolic relationship.', 'The power dissipated by an electrical resistance is given by the formula $P = I^2 R$. Because the metal wire is maintained at a constant temperature, its resistance $R$ remains constant. Therefore, power $P$ is directly proportional to the square of the current $I$ ($P \propto I^2$). Mathematically, this is a parabola that opens upwards and passes through the origin. Graph (3) correctly depicts this parabolic relationship.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
