INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('39da39d2-a8e1-58a1-b8f5-9f32c8793907', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 34, '<p>A set of parallel resistors and a set of series resistors are connected as shown in the figure. The resistance values of resistors may or may not be the same. Which of the following statements is always true?</p>', '<p>A set of parallel resistors and a set of series resistors are connected as shown in the figure. The resistance values of resistors may or may not be the same. Which of the following statements is always true?</p>', NULL, 'Let the equivalent resistance of the parallel set be $R_p$ and the series set be $R_s$. The total resistance of the circuit is $R_{total} = R_p + R_s$. <br> For resistors in series, the total equivalent resistance ($R_s$) is the sum of the individual resistances, meaning $R_s$ is strictly greater than any individual resistor in that series group. Since $R_{total}$ adds an additional positive resistance ($R_p$) to $R_s$, the total resistance of the entire network will always be greater than the resistance of any individual resistor located within the series set. Options 1 and 2 are false unless the resistor values happen to be identical.', 'Let the equivalent resistance of the parallel set be $R_p$ and the series set be $R_s$. The total resistance of the circuit is $R_{total} = R_p + R_s$. <br> For resistors in series, the total equivalent resistance ($R_s$) is the sum of the individual resistances, meaning $R_s$ is strictly greater than any individual resistor in that series group. Since $R_{total}$ adds an additional positive resistance ($R_p$) to $R_s$, the total resistance of the entire network will always be greater than the resistance of any individual resistor located within the series set. Options 1 and 2 are false unless the resistor values happen to be identical.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
