INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('727a8ff4-159d-4c0e-b238-f4a140df6b70', '39da39d2-a8e1-58a1-b8f5-9f32c8793907', 'The total resistance of the entire network is less than the resistance of any individual resistor in the network.', 'The total resistance of the entire network is less than the resistance of any individual resistor in the network.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('49a8200f-559e-5593-9c01-76bae66c0114', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 35, '<p>One electron is moving opposite to a uniform electric field ($E$) and another electron is moving perpendicular to a uniform magnetic field ($B$) as shown in figures (1) and (2). For each situation the de Broglie wavelength of the electrons respectively</p>', '<p>One electron is moving opposite to a uniform electric field ($E$) and another electron is moving perpendicular to a uniform magnetic field ($B$) as shown in figures (1) and (2). For each situation the de Broglie wavelength of the electrons respectively</p>', NULL, 'The de Broglie wavelength is given by $\lambda = \frac{h}{p} = \frac{h}{mv}$. <br> 1. **Electric Field:** An electron has a negative charge, so it experiences an electric force in the direction opposite to the electric field $E$. Because it is already moving opposite to $E$, this force acts in the direction of its motion, causing it to accelerate. Its velocity $v$ and momentum $p$ increase, so its de Broglie wavelength **decreases**. <br> 2. **Magnetic Field:** An electron moving perpendicular to a magnetic field experiences a force perpendicular to its velocity. This force acts as a centripetal force, changing only the direction of motion but keeping the speed $v$ (and magnitude of momentum) constant. Therefore, its de Broglie wavelength **does not change**.', 'The de Broglie wavelength is given by $\lambda = \frac{h}{p} = \frac{h}{mv}$. <br> 1. **Electric Field:** An electron has a negative charge, so it experiences an electric force in the direction opposite to the electric field $E$. Because it is already moving opposite to $E$, this force acts in the direction of its motion, causing it to accelerate. Its velocity $v$ and momentum $p$ increase, so its de Broglie wavelength **decreases**. <br> 2. **Magnetic Field:** An electron moving perpendicular to a magnetic field experiences a force perpendicular to its velocity. This force acts as a centripetal force, changing only the direction of motion but keeping the speed $v$ (and magnitude of momentum) constant. Therefore, its de Broglie wavelength **does not change**.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
