INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c4916b2c-0395-5924-ac77-b6439f13e8b3', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 40, '<p>Consider the logic circuit shown with three inputs A, B and C. What is the Boolean expression that best represents the output F of the circuit?</p>', '<p>Consider the logic circuit shown with three inputs A, B and C. What is the Boolean expression that best represents the output F of the circuit?</p>', NULL, 'The diagram represents a 2-to-1 multiplexer structure. It consists of an upper AND gate taking inputs $A$ and $\overline{B}$ (NOT B), producing $A\overline{B}$. A lower AND gate takes inputs $B$ and $C$, producing $BC$. The outputs of these two AND gates are fed into an OR gate. Therefore, the final Boolean expression for the output $F$ is the sum of these two products: $F = A\overline{B} + BC$.', 'The diagram represents a 2-to-1 multiplexer structure. It consists of an upper AND gate taking inputs $A$ and $\overline{B}$ (NOT B), producing $A\overline{B}$. A lower AND gate takes inputs $B$ and $C$, producing $BC$. The outputs of these two AND gates are fed into an OR gate. Therefore, the final Boolean expression for the output $F$ is the sum of these two products: $F = A\overline{B} + BC$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
