INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cfc39532-f2cf-511b-bfc1-f0582804794b', '42ec97a0-c035-569b-8306-b91ae72dbe2f', 44, '<p>For a satellite moving in a circular path around the earth the kinetic energy, gravitational potential energy and total energy are given by $K$, $V$ and $E$ respectively. Which of the following relationships is true?</p>', '<p>For a satellite moving in a circular path around the earth the kinetic energy, gravitational potential energy and total energy are given by $K$, $V$ and $E$ respectively. Which of the following relationships is true?</p>', NULL, 'For a satellite in a circular orbit, the necessary centripetal force is provided by gravity: $\frac{mv^2}{r} = \frac{GMm}{r^2}$. <br> Kinetic energy: $K = \frac{1}{2}mv^2 = \frac{GMm}{2r}$. <br> Gravitational potential energy: $V = -\frac{GMm}{r}$. Notice that $V = -2K$. <br> Total energy: $E = K + V = \frac{GMm}{2r} - \frac{GMm}{r} = -\frac{GMm}{2r}$. <br> Comparing $E$ and $K$, we clearly see that $E = -K$.', 'For a satellite in a circular orbit, the necessary centripetal force is provided by gravity: $\frac{mv^2}{r} = \frac{GMm}{r^2}$. <br> Kinetic energy: $K = \frac{1}{2}mv^2 = \frac{GMm}{2r}$. <br> Gravitational potential energy: $V = -\frac{GMm}{r}$. Notice that $V = -2K$. <br> Total energy: $E = K + V = \frac{GMm}{2r} - \frac{GMm}{r} = -\frac{GMm}{2r}$. <br> Comparing $E$ and $K$, we clearly see that $E = -K$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
