INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a4200274-1eeb-5dd1-8005-a785c69acf71', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 2, '<p>වැරදි වගන්තිය තෝරන්න.</p>', '<p>වැරදි වගන්තිය තෝරන්න.</p>', NULL, 'අයනික අරයන් සලකා බැලීමේදී, $K^+$ හි අරය (~138 pm) සහ $Mg^{2+}$ හි අරය (~72 pm) අතර විශාල වෙනසක් පවතී. විශාලත්වයෙන් වඩාත්ම ආසන්න වන්නේ විකර්ණ සම්බන්ධතාවය (diagonal relationship) පෙන්වන $Na^+$ (~102 pm) සහ $Ca^{2+}$ (~100 pm) යන අයන යුගලයයි. එබැවින් 4 වන ප්‍රකාශය වැරදිය.', 'අයනික අරයන් සලකා බැලීමේදී, $K^+$ හි අරය (~138 pm) සහ $Mg^{2+}$ හි අරය (~72 pm) අතර විශාල වෙනසක් පවතී. විශාලත්වයෙන් වඩාත්ම ආසන්න වන්නේ විකර්ණ සම්බන්ධතාවය (diagonal relationship) පෙන්වන $Na^+$ (~102 pm) සහ $Ca^{2+}$ (~100 pm) යන අයන යුගලයයි. එබැවින් 4 වන ප්‍රකාශය වැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0f539000-af1a-481e-99e0-1c17a8f45710', 'a4200274-1eeb-5dd1-8005-a785c69acf71', 'පවුලි බහිෂ්කාරක මූලධර්මය කාක්ෂිකයක තුන්වන ඉලෙක්ට්‍රෝනයක් පැවතීමේ හැකියාව බැහැර කරයි.', 'පවුලි බහිෂ්කාරක මූලධර්මය කාක්ෂිකයක තුන්වන ඉලෙක්ට්‍රෝනයක් පැවතීමේ හැකියාව බැහැර කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2fda0620-b982-443f-9a01-e502fcfb1453', 'a4200274-1eeb-5dd1-8005-a785c69acf71', 'පොටෑසියම් පරමාණුවක, ක්වොන්ටම් අංක $n=3$ (ප්‍රධාන ක්වොන්ටම් අංකය) සහ $m_l=0$ (චුම්බක ක්වොන්ටම් අංකය) ඇති ඉලෙක්ට්‍රෝන සංඛ්‍යාව 4 කි.', 'පොටෑසියම් පරමාණුවක, ක්වොන්ටම් අංක $n=3$ (ප්‍රධාන ක්වොන්ටම් අංකය) සහ $m_l=0$ (චුම්බක ක්වොන්ටම් අංකය) ඇති ඉලෙක්ට්‍රෝන සංඛ්‍යාව 4 කි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bbf76df8-a90a-4452-95da-b7304230d2b6', 'a4200274-1eeb-5dd1-8005-a785c69acf71', 'නයිට්‍රජන් (N) හි සංයුජතා ඉලෙක්ට්‍රෝනයකට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණය කාබන් (C) හි සංයුජතා ඉලෙක්ට්‍රෝනයකට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණයට වඩා විශාල වෙයි.', 'නයිට්‍රජන් (N) හි සංයුජතා ඉලෙක්ට්‍රෝනයකට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණය කාබන් (C) හි සංයුජතා ඉලෙක්ට්‍රෝනයකට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණයට වඩා විශාල වෙයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3e238b33-5fb5-4c8f-a713-fa7c0b505873', 'a4200274-1eeb-5dd1-8005-a785c69acf71', '$Na^+$, $Mg^{2+}$, $K^+$ සහ $Ca^{2+}$ අයන අතුරෙන් විශාලත්වයෙන් එකිනෙකට වඩාත්ම ආසන්න අයන දෙක වන්නේ $K^+$ සහ $Mg^{2+}$ ය.', '$Na^+$, $Mg^{2+}$, $K^+$ සහ $Ca^{2+}$ අයන අතුරෙන් විශාලත්වයෙන් එකිනෙකට වඩාත්ම ආසන්න අයන දෙක වන්නේ $K^+$ සහ $Mg^{2+}$ ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b536e952-f9b7-405c-82fa-d965fbaafac5', 'a4200274-1eeb-5dd1-8005-a785c69acf71', 'කාබන්වල ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය ඍණ වේ.', 'කාබන්වල ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය ඍණ වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a2f1a758-37e1-524b-8dd2-62ffedb42452', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 3, '<p>Be, B සහ O වල දෙවන අයනීකරණ ශක්තිය ($X^+(g) \rightarrow X^{2+}(g) + e$) වැඩිවන අනුපිළිවෙළ වනුයේ,</p>', '<p>Be, B සහ O වල දෙවන අයනීකරණ ශක්තිය ($X^+(g) \rightarrow X^{2+}(g) + e$) වැඩිවන අනුපිළිවෙළ වනුයේ,</p>', NULL, 'මූලද්‍රව්‍යවල පළමු ඉලෙක්ට්‍රෝනය ඉවත් කළ පසු ඉලෙක්ට්‍රෝන වින්‍යාසය මෙසේ වේ: $Be^+$ ($1s^2 2s^1$), $B^+$ ($1s^2 2s^2$), $O^+$ ($1s^2 2s^2 2p^3$).<br>$Be^+$ හි දෙවන ඉලෙක්ට්‍රෝනය ඉවත් වන්නේ අර්ධ වශයෙන් පිරුණු $2s$ උපශක්ති මට්ටමෙනි. $B^+$ හිදී එය පූර්ණ ලෙස පිරුණු $2s$ මට්ටමෙන් ඉවත් කළ යුතු බැවින් එය $Be^+$ ට වඩා වැඩි ශක්තියක් ගනී. $O^+$ හිදී ඉලෙක්ට්‍රෝනය ඉවත් වන්නේ අර්ධ වශයෙන් පිරුණු වඩාත් ස්ථායී $2p^3$ මට්ටමෙන් බැවින් ඊට අවශ්‍ය ශක්තිය ඉතා ඉහළ වේ. එබැවින් පිළිවෙළ $Be < B < O$ වේ.', 'මූලද්‍රව්‍යවල පළමු ඉලෙක්ට්‍රෝනය ඉවත් කළ පසු ඉලෙක්ට්‍රෝන වින්‍යාසය මෙසේ වේ: $Be^+$ ($1s^2 2s^1$), $B^+$ ($1s^2 2s^2$), $O^+$ ($1s^2 2s^2 2p^3$).<br>$Be^+$ හි දෙවන ඉලෙක්ට්‍රෝනය ඉවත් වන්නේ අර්ධ වශයෙන් පිරුණු $2s$ උපශක්ති මට්ටමෙනි. $B^+$ හිදී එය පූර්ණ ලෙස පිරුණු $2s$ මට්ටමෙන් ඉවත් කළ යුතු බැවින් එය $Be^+$ ට වඩා වැඩි ශක්තියක් ගනී. $O^+$ හිදී ඉලෙක්ට්‍රෝනය ඉවත් වන්නේ අර්ධ වශයෙන් පිරුණු වඩාත් ස්ථායී $2p^3$ මට්ටමෙන් බැවින් ඊට අවශ්‍ය ශක්තිය ඉතා ඉහළ වේ. එබැවින් පිළිවෙළ $Be < B < O$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
