INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8de4ea89-3050-5e91-8c29-29fd657a2331', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 7, '<p>නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'මෙම අණු වල අන්තර් අණුක බල සලකා බැලීමේදී: $CH_4$ හි ඇත්තේ දුර්වල ලන්ඩන් අපකිරණ බල වේ. Xe ද නිර්ධ්‍රැවීය නමුත් එය වඩා විශාල බැවින් අපකිරණ බල ප්‍රබල ය. $CH_3NH_2$ සහ $CH_3OH$ යන දෙකෙහිම හයිඩ්‍රජන් බන්ධන පවතින අතර, N ට වඩා O හි විද්‍යුත් සෘණතාව වැඩි බැවින් $CH_3OH$ හි හයිඩ්‍රජන් බන්ධන වඩාත් ප්‍රබල වේ. එබැවින් තාපාංක අනුපිළිවෙළ $CH_4 < Xe < CH_3NH_2 < CH_3OH$ වීම නිවැරදිය.', 'මෙම අණු වල අන්තර් අණුක බල සලකා බැලීමේදී: $CH_4$ හි ඇත්තේ දුර්වල ලන්ඩන් අපකිරණ බල වේ. Xe ද නිර්ධ්‍රැවීය නමුත් එය වඩා විශාල බැවින් අපකිරණ බල ප්‍රබල ය. $CH_3NH_2$ සහ $CH_3OH$ යන දෙකෙහිම හයිඩ්‍රජන් බන්ධන පවතින අතර, N ට වඩා O හි විද්‍යුත් සෘණතාව වැඩි බැවින් $CH_3OH$ හි හයිඩ්‍රජන් බන්ධන වඩාත් ප්‍රබල වේ. එබැවින් තාපාංක අනුපිළිවෙළ $CH_4 < Xe < CH_3NH_2 < CH_3OH$ වීම නිවැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e5d4e8ef-b082-42d7-9e20-a4d867b98726', '8de4ea89-3050-5e91-8c29-29fd657a2331', '$F^-$, $Cl^-$ සහ $S^{2-}$ අයනවල ධ්‍රැවණ ශීලතාව $F^- < S^{2-} < Cl^-$ යන පිළිවෙළට වැඩි වේ.', '$F^-$, $Cl^-$ සහ $S^{2-}$ අයනවල ධ්‍රැවණ ශීලතාව $F^- < S^{2-} < Cl^-$ යන පිළිවෙළට වැඩි වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0ea79fcb-f6d3-4ff4-b28b-95ed3fbc1a11', '8de4ea89-3050-5e91-8c29-29fd657a2331', '$Li^+$, $Na^+$ සහ $Mg^{2+}$ වල ධ්‍රැවීකරණ බලය $Mg^{2+} > Na^+ > Li^+$ යන පිළිවෙළට අඩු වේ.', '$Li^+$, $Na^+$ සහ $Mg^{2+}$ වල ධ්‍රැවීකරණ බලය $Mg^{2+} > Na^+ > Li^+$ යන පිළිවෙළට අඩු වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('03be2184-e81f-4c0e-b02b-93b99c7eddda', '8de4ea89-3050-5e91-8c29-29fd657a2331', 'O, F, Cl සහ S වල විද්‍යුත් සෘණතාව $F > O > S > Cl$ යන පිළිවෙළට අඩු වේ.', 'O, F, Cl සහ S වල විද්‍යුත් සෘණතාව $F > O > S > Cl$ යන පිළිවෙළට අඩු වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('973d78c9-b9ce-4c9f-aceb-9b3ec546cf40', '8de4ea89-3050-5e91-8c29-29fd657a2331', 'Xe, $CH_4$, $CH_3NH_2$ සහ $CH_3OH$ වල තාපාංක $CH_4 < Xe < CH_3NH_2 < CH_3OH$ යන පිළිවෙළට වැඩි වේ.', 'Xe, $CH_4$, $CH_3NH_2$ සහ $CH_3OH$ වල තාපාංක $CH_4 < Xe < CH_3NH_2 < CH_3OH$ යන පිළිවෙළට වැඩි වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7c79294c-16b8-4903-99ef-917766429886', '8de4ea89-3050-5e91-8c29-29fd657a2331', '$N_2$, $O_2$, $F_2$ සහ HF වල අන්තර් පරමාණුක බන්ධන දිග $N_2 < O_2 < F_2 < HF$ යන පිළිවෙළට වැඩි වේ.', '$N_2$, $O_2$, $F_2$ සහ HF වල අන්තර් පරමාණුක බන්ධන දිග $N_2 < O_2 < F_2 < HF$ යන පිළිවෙළට වැඩි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7c414252-87ce-52bc-896f-33a3ad60ad12', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 8, '<p>P සහ Q සංයෝග එකිනෙකෙහි පාරත්‍රිමාන සමාවයවික වේ. පහත දැක්වෙන ඒවායින් P සහ Q සංයෝගයන්හි අණුක සූත්‍රය විය හැක්කේ කුමක්ද?</p>', '<p>P සහ Q සංයෝග එකිනෙකෙහි පාරත්‍රිමාන සමාවයවික වේ. පහත දැක්වෙන ඒවායින් P සහ Q සංයෝගයන්හි අණුක සූත්‍රය විය හැක්කේ කුමක්ද?</p>', NULL, 'පාරත්‍රිමාන සමාවයවිකතාව (Stereoisomerism) පෙන්වීමට නම් සංයෝගයට ජ්‍යාමිතික හෝ ප්‍රකාශ සමාවයවිකතා ලක්ෂණ තිබිය යුතුය. ලබා දී ඇති අණුක සූත්‍ර අතුරින් $C_5H_{10}$ (උදාහරණයක් ලෙස pent-2-ene) හට cis- සහ trans- ජ්‍යාමිතික සමාවයවික පවතී. අනෙක් සරල ඇල්කේන සහ ඇල්කයින වලට මෙම ලක්ෂණය නොමැත.', 'පාරත්‍රිමාන සමාවයවිකතාව (Stereoisomerism) පෙන්වීමට නම් සංයෝගයට ජ්‍යාමිතික හෝ ප්‍රකාශ සමාවයවිකතා ලක්ෂණ තිබිය යුතුය. ලබා දී ඇති අණුක සූත්‍ර අතුරින් $C_5H_{10}$ (උදාහරණයක් ලෙස pent-2-ene) හට cis- සහ trans- ජ්‍යාමිතික සමාවයවික පවතී. අනෙක් සරල ඇල්කේන සහ ඇල්කයින වලට මෙම ලක්ෂණය නොමැත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
