INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('729d9843-dedd-4079-96d0-65d668d33301', '8fbdc9f9-4ea4-5ed8-b695-8e9b309bd33f', 'ඵල අණු සංඛ්‍යාව හා ප්‍රතික්‍රියක අණු සංඛ්‍යාව එකිනෙකට සමාන බැවින් $K_p$ වෙනස් නොවේ.', 'ඵල අණු සංඛ්‍යාව හා ප්‍රතික්‍රියක අණු සංඛ්‍යාව එකිනෙකට සමාන බැවින් $K_p$ වෙනස් නොවේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('60d3bac4-d44c-4078-909c-2b7c590e1f0a', '8fbdc9f9-4ea4-5ed8-b695-8e9b309bd33f', 'ආපසු ප්‍රතික්‍රියාව තාප අවශෝෂක බැවින් ඉදිරි ප්‍රතික්‍රියාවෙහි නැඹුරුතාවය වැඩි වී $K_p$ අඩු වේ.', 'ආපසු ප්‍රතික්‍රියාව තාප අවශෝෂක බැවින් ඉදිරි ප්‍රතික්‍රියාවෙහි නැඹුරුතාවය වැඩි වී $K_p$ අඩු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8af60ea5-8918-496b-bd9e-d3dc7cebc11e', '8fbdc9f9-4ea4-5ed8-b695-8e9b309bd33f', 'ඉදිරි ප්‍රතික්‍රියාව තාපදායක බැවින් ආපසු ප්‍රතික්‍රියාවෙහි නැඹුරුතාවය වැඩි වී $K_p$ අඩු වේ.', 'ඉදිරි ප්‍රතික්‍රියාව තාපදායක බැවින් ආපසු ප්‍රතික්‍රියාවෙහි නැඹුරුතාවය වැඩි වී $K_p$ අඩු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0dc005ae-edb3-52a9-a6e5-fdbad66189b4', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 12, '<p>$X(aq) + Y(aq) \rightarrow Z(aq)$ ප්‍රතික්‍රියාව සඳහා දී ඇති උෂ්ණත්වයකදී සිදු කළ ආරම්භක ශීඝ්‍රතා මැනීමේ පරීක්ෂණයක විස්තර පහත වගුවෙහි දක්වා ඇත.<br><br>පරීක්ෂණය 1: $[X(aq)]_0 = 0.40\ mol\ dm^{-3}$, $[Y(aq)]_0 = 0.10\ mol\ dm^{-3}$, ආරම්භක ශීඝ්‍රතාව = $R$<br>පරීක්ෂණය 2: $[X(aq)]_0 = 0.20\ mol\ dm^{-3}$, $[Y(aq)]_0 = 0.20\ mol\ dm^{-3}$, ආරම්භක ශීඝ්‍රතාව = ?<br><br>1 පරීක්ෂණයේදී $Z(aq)$ සෑදීමේ ආරම්භක ශීඝ්‍රතාවය $R$ වේ. ප්‍රතික්‍රියාව $X(aq)$ අනුබද්ධයෙන් පළමු පෙළ සහ $Y(aq)$ අනුබද්ධයෙන් දෙවන පෙළ වේ.<br>2 පරීක්ෂණයේදී $Z(aq)$ සෑදීමේ ආරම්භක ශීඝ්‍රතාවය වන්නේ,</p>', '<p>$X(aq) + Y(aq) \rightarrow Z(aq)$ ප්‍රතික්‍රියාව සඳහා දී ඇති උෂ්ණත්වයකදී සිදු කළ ආරම්භක ශීඝ්‍රතා මැනීමේ පරීක්ෂණයක විස්තර පහත වගුවෙහි දක්වා ඇත.<br><br>පරීක්ෂණය 1: $[X(aq)]_0 = 0.40\ mol\ dm^{-3}$, $[Y(aq)]_0 = 0.10\ mol\ dm^{-3}$, ආරම්භක ශීඝ්‍රතාව = $R$<br>පරීක්ෂණය 2: $[X(aq)]_0 = 0.20\ mol\ dm^{-3}$, $[Y(aq)]_0 = 0.20\ mol\ dm^{-3}$, ආරම්භක ශීඝ්‍රතාව = ?<br><br>1 පරීක්ෂණයේදී $Z(aq)$ සෑදීමේ ආරම්භක ශීඝ්‍රතාවය $R$ වේ. ප්‍රතික්‍රියාව $X(aq)$ අනුබද්ධයෙන් පළමු පෙළ සහ $Y(aq)$ අනුබද්ධයෙන් දෙවන පෙළ වේ.<br>2 පරීක්ෂණයේදී $Z(aq)$ සෑදීමේ ආරම්භක ශීඝ්‍රතාවය වන්නේ,</p>', NULL, 'ශීඝ්‍රතා නියමය: $Rate = k[X]^1[Y]^2$<br>පළමු පරීක්ෂණය සඳහා: $R = k(0.40)(0.10)^2 = k(0.40)(0.01) = 0.004k$<br>දෙවන පරීක්ෂණය සඳහා: $Rate_2 = k(0.20)(0.20)^2 = k(0.20)(0.04) = 0.008k$<br>සංසන්දනය කිරීමෙන්: $Rate_2 = 2 \times 0.004k = 2R$ වේ.', 'ශීඝ්‍රතා නියමය: $Rate = k[X]^1[Y]^2$<br>පළමු පරීක්ෂණය සඳහා: $R = k(0.40)(0.10)^2 = k(0.40)(0.01) = 0.004k$<br>දෙවන පරීක්ෂණය සඳහා: $Rate_2 = k(0.20)(0.20)^2 = k(0.20)(0.04) = 0.008k$<br>සංසන්දනය කිරීමෙන්: $Rate_2 = 2 \times 0.004k = 2R$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
