INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ce6344ec-9c3c-499f-8881-6f8fe703e4ef', '9fc0b02b-7ba6-5780-8023-b2c63c3b255c', 'ඒක-භාස්මික දුබල අම්ලයක්, ඒක-ආම්ලික ප්‍රබල භස්මයක් සමග', 'ඒක-භාස්මික දුබල අම්ලයක්, ඒක-ආම්ලික ප්‍රබල භස්මයක් සමග', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('09fdc661-2ab0-5cdb-9de3-cec1900ccde5', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 16, '<p>s සහ p ගොනුවල මූලද්‍රව්‍ය සම්බන්ධයෙන් පහත දී ඇති කුමන ප්‍රකාශය අසත්‍ය ද?</p>', '<p>s සහ p ගොනුවල මූලද්‍රව්‍ය සම්බන්ධයෙන් පහත දී ඇති කුමන ප්‍රකාශය අසත්‍ය ද?</p>', NULL, 'දෙවන කාණ්ඩයේ (Alkaline earth metals) හයිඩ්‍රොක්සයිඩ වල ද්‍රාව්‍යතාවය කාණ්ඩය පහළට යන විට **වැඩි වන** අතර ($Mg(OH)_2$ අද්‍රාව්‍ය වන අතර $Ba(OH)_2$ හොඳින් ද්‍රාව්‍ය වේ), සල්ෆේට වල ද්‍රාව්‍යතාවය කාණ්ඩය පහළට යන විට **අඩු වේ** ($MgSO_4$ ද්‍රාව්‍ය වන අතර $BaSO_4$ අද්‍රාව්‍ය වේ). එබැවින් 3 වන ප්‍රකාශය අසත්‍ය වේ.', 'දෙවන කාණ්ඩයේ (Alkaline earth metals) හයිඩ්‍රොක්සයිඩ වල ද්‍රාව්‍යතාවය කාණ්ඩය පහළට යන විට **වැඩි වන** අතර ($Mg(OH)_2$ අද්‍රාව්‍ය වන අතර $Ba(OH)_2$ හොඳින් ද්‍රාව්‍ය වේ), සල්ෆේට වල ද්‍රාව්‍යතාවය කාණ්ඩය පහළට යන විට **අඩු වේ** ($MgSO_4$ ද්‍රාව්‍ය වන අතර $BaSO_4$ අද්‍රාව්‍ය වේ). එබැවින් 3 වන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d04d0b75-9bb0-4ecb-af43-47363cacc656', '09fdc661-2ab0-5cdb-9de3-cec1900ccde5', 'සෙනෝන් (Xe) නිෂ්ක්‍රිය වායුවක් වුවත් ඔක්සිකරණ අංක +2, +4 සහ +6 වන සංයෝග සාදයි.', 'සෙනෝන් (Xe) නිෂ්ක්‍රිය වායුවක් වුවත් ඔක්සිකරණ අංක +2, +4 සහ +6 වන සංයෝග සාදයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cd6c1b67-d5e9-4e6f-a168-13316866fe48', '09fdc661-2ab0-5cdb-9de3-cec1900ccde5', 'හයිඩ්‍රජන් හේලයිඩ අතුරෙන්, වැඩිම බන්ධන විඝටන ශක්තිය ඇත්තේ HF වලට ය.', 'හයිඩ්‍රජන් හේලයිඩ අතුරෙන්, වැඩිම බන්ධන විඝටන ශක්තිය ඇත්තේ HF වලට ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f560cc86-f8bc-4dee-b4cd-efd161c691c7', '09fdc661-2ab0-5cdb-9de3-cec1900ccde5', 'දෙවන (II) කාණ්ඩයේ මූලද්‍රව්‍යයන්හි හයිඩ්‍රොක්සයිඩවල ජලයෙහි ද්‍රාව්‍යතාවය කාණ්ඩයේ පහළට යන විට අඩුවන අතර, ඒවායෙහි සල්ෆේට වල ද්‍රාව්‍යතාවය වැඩි වේ.', 'දෙවන (II) කාණ්ඩයේ මූලද්‍රව්‍යයන්හි හයිඩ්‍රොක්සයිඩවල ජලයෙහි ද්‍රාව්‍යතාවය කාණ්ඩයේ පහළට යන විට අඩුවන අතර, ඒවායෙහි සල්ෆේට වල ද්‍රාව්‍යතාවය වැඩි වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('86b18530-6f8e-4d28-ae11-ba70d5e665de', '09fdc661-2ab0-5cdb-9de3-cec1900ccde5', 'පළමුවන (I) කාණ්ඩයේ ලෝහ අතුරෙන් (Li සිට Cs දක්වා) සීසියම් වලට අඩුම ද්‍රවාංකය ඇත.', 'පළමුවන (I) කාණ්ඩයේ ලෝහ අතුරෙන් (Li සිට Cs දක්වා) සීසියම් වලට අඩුම ද්‍රවාංකය ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('833313dc-3b33-4523-b9ae-2cef14893b61', '09fdc661-2ab0-5cdb-9de3-cec1900ccde5', '$NH_2OH$ හි නයිට්‍රජන්වල ඔක්සිකරණ අංකය -1 වේ.', '$NH_2OH$ හි නයිට්‍රජන්වල ඔක්සිකරණ අංකය -1 වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('18aab97d-27b3-597e-bc2e-c28e5718688f', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 17, '<p>$25^{\circ}C$ දී බීකරයක ඇති $x\ mol\ dm^{-3}$ $CH_3COOH(aq)$ ද්‍රාවණ $V_1\ cm^3$ කට $y\ mol\ dm^{-3}$ ($y > x$) $NaOH(aq)$ ද්‍රාවණ $V_2\ cm^3$ ($V_2 > V_1$) එකතු කරන ලදී. අවසාන මිශ්‍රණයෙහි pH අගය වනුයේ, ($K_w$ යනු $25^{\circ}C$ දී ජලයෙහි අයනික ගුණිතය වේ.)</p>', '<p>$25^{\circ}C$ දී බීකරයක ඇති $x\ mol\ dm^{-3}$ $CH_3COOH(aq)$ ද්‍රාවණ $V_1\ cm^3$ කට $y\ mol\ dm^{-3}$ ($y > x$) $NaOH(aq)$ ද්‍රාවණ $V_2\ cm^3$ ($V_2 > V_1$) එකතු කරන ලදී. අවසාන මිශ්‍රණයෙහි pH අගය වනුයේ, ($K_w$ යනු $25^{\circ}C$ දී ජලයෙහි අයනික ගුණිතය වේ.)</p>', NULL, '$CH_3COOH$ මවුල ගණන = $\frac{xV_1}{1000}$<br>$NaOH$ මවුල ගණන = $\frac{yV_2}{1000}$<br>මෙහි $y > x$ සහ $V_2 > V_1$ බැවින් $NaOH$ ප්‍රතික්‍රියාවෙන් පසු ඉතිරි වේ. ප්‍රතික්‍රියාවෙන් පසු ඉතිරි $OH^-$ මවුල ගණන = $\frac{yV_2 - xV_1}{1000}$<br>මුළු පරිමාව = $\frac{V_1 + V_2}{1000}\ dm^3$<br>ද්‍රාවණයේ $[OH^-] = \frac{V_2y - V_1x}{V_1 + V_2}$<br>$pOH = -\log[OH^-] = -\log\left\{\frac{V_2y - V_1x}{V_1 + V_2}\right\}$<br>$pH = pK_w - pOH = pK_w + \log\left\{\frac{V_2y - V_1x}{V_1 + V_2}\right\}$', '$CH_3COOH$ මවුල ගණන = $\frac{xV_1}{1000}$<br>$NaOH$ මවුල ගණන = $\frac{yV_2}{1000}$<br>මෙහි $y > x$ සහ $V_2 > V_1$ බැවින් $NaOH$ ප්‍රතික්‍රියාවෙන් පසු ඉතිරි වේ. ප්‍රතික්‍රියාවෙන් පසු ඉතිරි $OH^-$ මවුල ගණන = $\frac{yV_2 - xV_1}{1000}$<br>මුළු පරිමාව = $\frac{V_1 + V_2}{1000}\ dm^3$<br>ද්‍රාවණයේ $[OH^-] = \frac{V_2y - V_1x}{V_1 + V_2}$<br>$pOH = -\log[OH^-] = -\log\left\{\frac{V_2y - V_1x}{V_1 + V_2}\right\}$<br>$pH = pK_w - pOH = pK_w + \log\left\{\frac{V_2y - V_1x}{V_1 + V_2}\right\}$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('68cab3b9-37ba-4494-ac00-b6e82704b5a9', '18aab97d-27b3-597e-bc2e-c28e5718688f', '$pK_w - \log\left\{\frac{V_2y - V_1x}{V_1 + V_2}\right\}$', '$pK_w - \log\left\{\frac{V_2y - V_1x}{V_1 + V_2}\right\}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d600f422-8155-45ff-99c9-0f05f226cb72', '18aab97d-27b3-597e-bc2e-c28e5718688f', '$pK_w + \log\left\{\frac{V_2y - V_1x}{V_1 + V_2}\right\}$', '$pK_w + \log\left\{\frac{V_2y - V_1x}{V_1 + V_2}\right\}$', NULL, 'sanitized', 'v1', 1, 0);
