INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('47e24cb2-3a4d-4f99-a4b3-d386f19350da', '5e6082b7-114f-5b15-b9d8-9557d4e85e95', '$4H_2(g) + 2O_2(g) \rightarrow 4H_2O(g)$ ප්‍රතික්‍රියාව සඳහා $967.4\ kJ$ ක තාප ශක්තියක් පිට වේ.', '$4H_2(g) + 2O_2(g) \rightarrow 4H_2O(g)$ ප්‍රතික්‍රියාව සඳහා $967.4\ kJ$ ක තාප ශක්තියක් පිට වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c7b5491b-f841-499c-8ef2-35f16e40c7a2', '5e6082b7-114f-5b15-b9d8-9557d4e85e95', 'ප්‍රතික්‍රියා වූ $O_2(g)$ මවුල එකක් සඳහා $241.85\ kJ$ ක තාප ශක්තියක් පිට වේ.', 'ප්‍රතික්‍රියා වූ $O_2(g)$ මවුල එකක් සඳහා $241.85\ kJ$ ක තාප ශක්තියක් පිට වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('000744e4-32a8-570f-a4a5-1a830352dde6', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 19, '<p>පහත සඳහන් කුමන වගන්තිය ගැල්වානීය කෝෂයක් සඳහා වැරදි වේද?</p>', '<p>පහත සඳහන් කුමන වගන්තිය ගැල්වානීය කෝෂයක් සඳහා වැරදි වේද?</p>', NULL, 'ගැල්වානීය කෝෂයක (Galvanic cell) ඇනෝඩයේදී ඔක්සිකරණය සිදුවී ඉලෙක්ට්‍රෝන නිදහස් කරන බැවින් ඇනෝඩය ඍණ (-) ලෙස සලකනු ලැබේ. කැතෝඩයේදී ඔක්සිහරණය සිදුවී ඉලෙක්ට්‍රෝන ලබාගන්නා බැවින් එය ධන (+) ලෙස සලකනු ලැබේ. එබැවින් ''කැතෝඩය ඍණ ආරෝපිත වේ'' යන 3 වන ප්‍රකාශය වැරදිය.', 'ගැල්වානීය කෝෂයක (Galvanic cell) ඇනෝඩයේදී ඔක්සිකරණය සිදුවී ඉලෙක්ට්‍රෝන නිදහස් කරන බැවින් ඇනෝඩය ඍණ (-) ලෙස සලකනු ලැබේ. කැතෝඩයේදී ඔක්සිහරණය සිදුවී ඉලෙක්ට්‍රෝන ලබාගන්නා බැවින් එය ධන (+) ලෙස සලකනු ලැබේ. එබැවින් ''කැතෝඩය ඍණ ආරෝපිත වේ'' යන 3 වන ප්‍රකාශය වැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
