INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('abf350c5-6cbc-54e1-a8ae-567f3ea9c7b3', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 22, '<p>සම්මත උෂ්ණත්වයේ හා පීඩනයේ පවතින සර්වසම දෘඪ සංවෘත බඳුන් දෙකක් තුළ $H_2(g)$ 1.0 mol ක් හා $O_2(g)$ 2.0 mol ක් අඩංගු වේ. ඉහත පද්ධති දෙක සම්බන්ධව, පහත සඳහන් කුමක් සත්‍ය වේද?</p>', '<p>සම්මත උෂ්ණත්වයේ හා පීඩනයේ පවතින සර්වසම දෘඪ සංවෘත බඳුන් දෙකක් තුළ $H_2(g)$ 1.0 mol ක් හා $O_2(g)$ 2.0 mol ක් අඩංගු වේ. ඉහත පද්ධති දෙක සම්බන්ධව, පහත සඳහන් කුමක් සත්‍ය වේද?</p>', NULL, 'පරිපූර්ණ වායු සඳහා මධ්‍යන්‍ය චාලක ශක්තිය කෙල්වින් උෂ්ණත්වයට පමණක් අනුලෝමව සමානුපාතික වේ ($E_k = \frac{3}{2}RT$). වායු දෙකම පවතින්නේ සම්මත උෂ්ණත්වයේ (එකම උෂ්ණත්වයේ) බැවින් ඒවායේ මධ්‍යන්‍ය චාලක ශක්තිය සමාන වේ.', 'පරිපූර්ණ වායු සඳහා මධ්‍යන්‍ය චාලක ශක්තිය කෙල්වින් උෂ්ණත්වයට පමණක් අනුලෝමව සමානුපාතික වේ ($E_k = \frac{3}{2}RT$). වායු දෙකම පවතින්නේ සම්මත උෂ්ණත්වයේ (එකම උෂ්ණත්වයේ) බැවින් ඒවායේ මධ්‍යන්‍ය චාලක ශක්තිය සමාන වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('050c3c35-4340-4054-9b62-c33f4ef291dc', 'abf350c5-6cbc-54e1-a8ae-567f3ea9c7b3', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම මධ්‍ය - චාලක ශක්තියක් ඇත.', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම මධ්‍ය - චාලක ශක්තියක් ඇත.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c5bc9418-0d41-4169-8293-f3d7febd1af0', 'abf350c5-6cbc-54e1-a8ae-567f3ea9c7b3', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම මධ්‍ය - වේගයක් ඇත.', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම මධ්‍ය - වේගයක් ඇත.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ebf27bc5-012a-419e-a585-c71846b41945', 'abf350c5-6cbc-54e1-a8ae-567f3ea9c7b3', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම ස්කන්ධයක් ඇත.', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම ස්කන්ධයක් ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1dbf3bce-2998-4a6e-9e5d-a72ca8fece1e', 'abf350c5-6cbc-54e1-a8ae-567f3ea9c7b3', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම ඝනත්වයක් ඇත.', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම ඝනත්වයක් ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7c302ffa-b300-4f5f-9e0f-8ad8ee77d3bc', 'abf350c5-6cbc-54e1-a8ae-567f3ea9c7b3', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම විසර්ජන වේගයක් ඇත.', '$H_2(g)$ හා $O_2(g)$ දෙකටම එකම විසර්ජන වේගයක් ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5fe4758d-5061-5815-a24f-b8c3347433ba', '4d515b1d-c1d3-5f47-87b2-81d2a293134a', 23, '<p>25°C දී $X(s)$ ඝනයෙහි මවුලික සද්‍රාවණ (dissolution) එන්ට්‍රොපි වෙනස $\Delta S_{dissol}^{\circ}$ $70\ J\ K^{-1}\ mol^{-1}$ හා $X(s)$ හි මවුලික එන්ට්‍රොපිය $100\ J\ K^{-1}\ mol^{-1}$ වේ. පහත සඳහන් කුමක් $X(aq)$ හි මවුලික එන්ට්‍රොපිය ($J\ K^{-1}\ mol^{-1}$) දක්වයිද?</p>', '<p>25°C දී $X(s)$ ඝනයෙහි මවුලික සද්‍රාවණ (dissolution) එන්ට්‍රොපි වෙනස $\Delta S_{dissol}^{\circ}$ $70\ J\ K^{-1}\ mol^{-1}$ හා $X(s)$ හි මවුලික එන්ට්‍රොපිය $100\ J\ K^{-1}\ mol^{-1}$ වේ. පහත සඳහන් කුමක් $X(aq)$ හි මවුලික එන්ට්‍රොපිය ($J\ K^{-1}\ mol^{-1}$) දක්වයිද?</p>', NULL, 'සද්‍රාවණ එන්ට්‍රොපි වෙනස, $\Delta S_{dissol}^{\circ} = S^{\circ}_{\text{ඵල}} - S^{\circ}_{\text{ප්‍රතික්‍රියක}}$ වේ.<br>එනම්, $\Delta S_{dissol}^{\circ} = S^{\circ}(X(aq)) - S^{\circ}(X(s))$<br>$70 = S^{\circ}(X(aq)) - 100$<br>$S^{\circ}(X(aq)) = 100 + 70 = 170\ J\ K^{-1}\ mol^{-1}$.', 'සද්‍රාවණ එන්ට්‍රොපි වෙනස, $\Delta S_{dissol}^{\circ} = S^{\circ}_{\text{ඵල}} - S^{\circ}_{\text{ප්‍රතික්‍රියක}}$ වේ.<br>එනම්, $\Delta S_{dissol}^{\circ} = S^{\circ}(X(aq)) - S^{\circ}(X(s))$<br>$70 = S^{\circ}(X(aq)) - 100$<br>$S^{\circ}(X(aq)) = 100 + 70 = 170\ J\ K^{-1}\ mol^{-1}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
