INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c2e9003b-8cb3-42de-8eed-0b84e4ead38a', 'a4c62c16-2f19-538b-8abd-486074c1424c', 'පළමුවැනි ප්‍රකාශය අසත්‍ය වන අතර, දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', 'පළමුවැනි ප්‍රකාශය අසත්‍ය වන අතර, දෙවැනි ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('27e8c648-f7e5-5c24-b3a5-e971c5a4f1d6', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 1, '<p>අයිතිය/ බල පත්‍රය සම්බන්ධයෙන් සැලකූ විට වෙනස් වර්ගවල මෘදුකාංග ඇතුළත් වන්නේ පහත කුමන යුගලයේ ද?</p>', '<p>අයිතිය/ බල පත්‍රය සම්බන්ධයෙන් සැලකූ විට වෙනස් වර්ගවල මෘදුකාංග ඇතුළත් වන්නේ පහත කුමන යුගලයේ ද?</p>', NULL, 'මෘදුකාංග අයිතිය (licensing) අනුව ප්‍රධාන වශයෙන් හිමිකම් සහිත (proprietary) සහ විවෘත මූලාශ්‍ර (open-source) ලෙස වර්ග කෙරේ. අනෙකුත් විකල්ප මෘදුකාංගවල භාවිතය (usage) මත පදනම් වූ වර්ගීකරණයන් වේ.', 'මෘදුකාංග අයිතිය (licensing) අනුව ප්‍රධාන වශයෙන් හිමිකම් සහිත (proprietary) සහ විවෘත මූලාශ්‍ර (open-source) ලෙස වර්ග කෙරේ. අනෙකුත් විකල්ප මෘදුකාංගවල භාවිතය (usage) මත පදනම් වූ වර්ගීකරණයන් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
