INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('55b39951-08f2-43ca-93f4-bf81c724918c', '27e8c648-f7e5-5c24-b3a5-e971c5a4f1d6', 'හිමිකම් සහිත (proprietary) මෘදුකාංග සහ විවෘත මූලාශ්‍ර මෘදුකාංග', 'හිමිකම් සහිත (proprietary) මෘදුකාංග සහ විවෘත මූලාශ්‍ර මෘදුකාංග', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9f9b23af-6694-4967-8691-f20960238dd8', '27e8c648-f7e5-5c24-b3a5-e971c5a4f1d6', 'හිමිකම සහිත මෘදුකාංග සහ පද්ධති (system) මෘදුකාංග', 'හිමිකම සහිත මෘදුකාංග සහ පද්ධති (system) මෘදුකාංග', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fe7cbb01-bb0f-4ff7-a61c-9300710bf2d2', '27e8c648-f7e5-5c24-b3a5-e971c5a4f1d6', 'පද්ධති මෘදුකාංග සහ උපයෝගිතා මෘදුකාංග', 'පද්ධති මෘදුකාංග සහ උපයෝගිතා මෘදුකාංග', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dbe39aec-40f2-5460-bd0c-7868b612abb3', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 2, '<p>පහත කවරක් කාණ්ඩ සැකසුම (batch processing) සඳහා හොඳ උදාහරණයක් වේ ද?</p>', '<p>පහත කවරක් කාණ්ඩ සැකසුම (batch processing) සඳහා හොඳ උදාහරණයක් වේ ද?</p>', NULL, 'වේතන (payroll) සැකසීමේ පද්ධතියක් යනු දත්ත යම් කාලයක් පුරා එක්රැස් කර, පසුව එක්වරක් සකසන (batch processing) පද්ධතියකට කදිම උදාහරණයකි. අනෙකුත් පද්ධති තත්‍ය කාලීන (real-time) පද්ධති වේ.', 'වේතන (payroll) සැකසීමේ පද්ධතියක් යනු දත්ත යම් කාලයක් පුරා එක්රැස් කර, පසුව එක්වරක් සකසන (batch processing) පද්ධතියකට කදිම උදාහරණයකි. අනෙකුත් පද්ධති තත්‍ය කාලීන (real-time) පද්ධති වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('af3d30dd-65a3-4f78-b6bd-e7a75f91f8bd', 'dbe39aec-40f2-5460-bd0c-7868b612abb3', 'ගුවන් යානා පාලක (air traffic control) පද්ධතියක්', 'ගුවන් යානා පාලක (air traffic control) පද්ධතියක්', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c90fc9e4-fb91-4bbc-bacf-e9398b87e451', 'dbe39aec-40f2-5460-bd0c-7868b612abb3', 'රියැදුරු රහිත මෝටර් කාරයක (autonomous car) පවතින ධාවන පද්ධතිය', 'රියැදුරු රහිත මෝටර් කාරයක (autonomous car) පවතින ධාවන පද්ධතිය', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('89b9aa52-1aef-4546-9b92-9f043e3008f8', 'dbe39aec-40f2-5460-bd0c-7868b612abb3', 'දැඩි සත්කාර ඒකක (ICU) රෝගීන් නිරීක්ෂණ හා සත්කාර පද්ධතිය', 'දැඩි සත්කාර ඒකක (ICU) රෝගීන් නිරීක්ෂණ හා සත්කාර පද්ධතිය', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('46dfb0de-39bd-414c-bf2d-7475692774ed', 'dbe39aec-40f2-5460-bd0c-7868b612abb3', 'වේතන (payroll) සැකසීමේ පද්ධතිය', 'වේතන (payroll) සැකසීමේ පද්ධතිය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d1379f50-29bb-4e62-ab97-76ff912ae4d3', 'dbe39aec-40f2-5460-bd0c-7868b612abb3', 'න්‍යෂ්ටික බලාගාර පාලන පද්ධතිය', 'න්‍යෂ්ටික බලාගාර පාලන පද්ධතිය', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a42e9976-3bcd-530e-94a7-d4c19ad7099b', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 3, '<p>ධාරිතාවය හා ප්‍රවේශ වේගය අනුව වෙනස්වන විවිධ ආචයන උපාංග පවතී.<br>නිහිත මතකය, L2 නිහිත මතකය, ප්‍රධාන මතකය, රෙජිස්තර හා දෘඪ ඩිස්කය යන ආචයන උපාංගයන්ගේ ධාරිතාවේ හා ප්‍රවේශ වේගයේ වෙනස්කම් දැක්වෙන රූපය සලකා බලන්න.<br>එහි දක්වා ඇති පරිදි, ඉහළ සිට පහළට ධාරිතාව වැඩි වන අතර, ප්‍රවේශ වේගය අඩු වේ.<br><br>ඉහත රූපයේ A, B, C, D හා E සඳහා කුමක් නිවැරදි වන්නේ ද?</p>
