INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('164ae47c-437f-5bb9-885a-b36437763c27', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 5, '<p>$01011100_2$ සහ $11111001_2$ යන ද්වීමය සංඛ්‍යා දෙක අතර බිටු අනුසාරිත XOR මෙහෙයුමේ නිවැරදි ප්‍රතිඵලය කුමක්ද?</p>', '<p>$01011100_2$ සහ $11111001_2$ යන ද්වීමය සංඛ්‍යා දෙක අතර බිටු අනුසාරිත XOR මෙහෙයුමේ නිවැරදි ප්‍රතිඵලය කුමක්ද?</p>', NULL, 'XOR මෙහෙයුමේදී ආදාන දෙක අසමාන නම් ප්‍රතිදානය 1 වේ, සමාන නම් 0 වේ.<br>$01011100_2 \oplus 11111001_2 = 10100101_2$', 'XOR මෙහෙයුමේදී ආදාන දෙක අසමාන නම් ප්‍රතිදානය 1 වේ, සමාන නම් 0 වේ.<br>$01011100_2 \oplus 11111001_2 = 10100101_2$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
