INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('eb8dc16d-2318-5afc-86fe-b20bf48a13e7', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 7, '<p>ෂඩ්දශමය $88.8_{16}$ ට තුල්‍ය වන නිවැරදි දශමය සංඛ්‍යාව කුමක් ද?</p>', '<p>ෂඩ්දශමය $88.8_{16}$ ට තුල්‍ය වන නිවැරදි දශමය සංඛ්‍යාව කුමක් ද?</p>', NULL, '$88.8_{16}$ දශමයට හැරවීම: $8 \times 16^1 + 8 \times 16^0 + 8 \times 16^{-1} = 128 + 8 + 0.5 = 136.5_{10}$.', '$88.8_{16}$ දශමයට හැරවීම: $8 \times 16^1 + 8 \times 16^0 + 8 \times 16^{-1} = 128 + 8 + 0.5 = 136.5_{10}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
