INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('28cb98dd-43fd-4a5f-877c-a7d1a5f87907', '667b238c-f6b2-5825-a531-3d667c0f3988', 'ක්‍රියායනයක පිටුවල අතථ්‍ය ලිපින හා භෞතික ලිපින අතර අනුරූපණයන් (mapping) තබාගන්නා වූ මෙහෙයුම් පද්ධති දත්ත ව්‍යුහයකි.', 'ක්‍රියායනයක පිටුවල අතථ්‍ය ලිපින හා භෞතික ලිපින අතර අනුරූපණයන් (mapping) තබාගන්නා වූ මෙහෙයුම් පද්ධති දත්ත ව්‍යුහයකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('60091060-cc66-4f49-ae9b-327c70657848', '667b238c-f6b2-5825-a531-3d667c0f3988', 'ක්‍රියායනයක අතථ්‍ය මතකයේ ඇති පිටු ගණන් තබාගන්නා වු සකසනයේ ඇති දෘඩාංග කොටසකි.', 'ක්‍රියායනයක අතථ්‍ය මතකයේ ඇති පිටු ගණන් තබාගන්නා වු සකසනයේ ඇති දෘඩාංග කොටසකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2162e8f0-0b24-5038-86b1-e6f179056cdd', '4e4b22e6-dd8b-5eba-9a89-0d197c4c5007', 12, '<p>ඩිස්කයක එක් කාණ්ඩයක (block) විශාලත්වය 4KB වේ. එම ඩිස්කයේ ගොනු විභජන වගුවේ (FAT) කොටසක් එක්තරා අවස්ථාවකදී පහත ආකාරයේ වේ.<br>FAT දත්ත: 100->101, 101->103, 102->-1, 103->104, 104->-1.<br><br>myprog.py ගොනුවේ නාමාවලි තොරතුර හා myprog.py ගොනුව සඳහා ඩිස්කයේ වෙන් කර ඇති ඉඩ ප්‍රමාණය පිළිවෙළින් දක්වන්නේ පහත කවරක් ද?</p>
